-- ---------------------------------------------------------------- orders
-- Left half: Shopify's copy (written only by the Shopify sync).
-- Right half: our status, hold and alert summary (written only by our team and jobs).
create table if not exists ops.orders (
  id                  bigint primary key,                               -- Shopify order id
  store               text not null references ops.stores(id),
  name                text not null,                                    -- #RBP7752
  customer_id         bigint,
  customer_name       text,
  email               text,
  phone               text,
  ship_name           text,
  ship_address1       text,
  ship_address2       text,
  ship_city           text,
  ship_province       text,
  ship_zip            text,
  ship_country        text,
  placed_at           timestamptz not null,
  shop_updated_at     timestamptz not null,                             -- older incoming messages are ignored
  cancelled_at        timestamptz,
  cancel_reason       text,
  financial_status    text,
  fulfillment_status  text,
  currency            text not null default 'USD',
  subtotal            numeric(12,2),
  discounts           numeric(12,2),
  shipping_charged    numeric(12,2),
  tax                 numeric(12,2),
  total               numeric(12,2),
  refunded_amount     numeric(12,2) not null default 0,
  tags                text[] not null default '{}',
  note                text,
  risk_level          text,
  raw                 jsonb,
  synced_at           timestamptz not null default now(),
  -- ours
  stage               text not null default 'new' check (stage in (
                        'new','checked','routed','in_production','packed','shipped','transit',
                        'delivered','closed','on_hold','cancelled','return_open')),
  stage_at            timestamptz not null default now(),
  due_at              timestamptz,
  late                boolean not null default false,
  checked_by          text,
  checked_at          timestamptz,
  hold_reason         text,
  hold_by             text,
  hold_at             timestamptz,
  dispute             text,
  open_alerts         int not null default 0,
  worst_alert         text check (worst_alert in ('red','amber')),
  closed_at           timestamptz,
  updated_by          text,
  updated_at          timestamptz not null default now(),
  -- FLOWMERCE ADDITION: where this row came from, for traceability of the migration.
  origin              text not null default 'shopify_sync' check (origin in ('shopify_sync','tracker_import'))
);
-- Not unique on purpose: imported data must never fail a whole refresh over one odd order name.
create index if not exists orders_store_name on ops.orders (store, name);
create index if not exists orders_open on ops.orders (store, stage, due_at) where closed_at is null;
create index if not exists orders_placed on ops.orders (store, placed_at desc);
drop trigger if exists orders_updated_at on ops.orders;
create trigger orders_updated_at before update on ops.orders
  for each row execute function ops.set_updated_at();

-- ---------------------------------------------------------------- items
create table if not exists ops.items (
  id             bigint primary key,                                   -- Shopify line item id
  order_id       bigint not null references ops.orders(id) on delete cascade,
  store          text not null references ops.stores(id),
  sku            text,
  title          text not null,
  variant_title  text,
  product_id     bigint,
  variant_id     bigint,
  image_url      text,
  qty            int not null,
  current_qty    int not null,
  refunded_qty   int not null default 0,
  fulfilled_qty  int not null default 0,
  open_qty       int not null default 0,                               -- the only number we ship against
  price          numeric(12,2),
  discount       numeric(12,2) not null default 0,
  route          text check (route in ('mcf','india','make','skip')),
  send_qty       int check (send_qty is null or send_qty >= 0),
  out_of_stock   boolean not null default false,
  shelf          text,
  shelf_qty      int,
  ppc_route      text,                                                 -- from the ERP
  erp_order_no   text,                                                 -- from the ERP
  updated_by     text,
  updated_at     timestamptz not null default now()
);
create index if not exists items_order on ops.items (order_id);
create index if not exists items_sku on ops.items (store, sku);
drop trigger if exists items_updated_at on ops.items;
create trigger items_updated_at before update on ops.items
  for each row execute function ops.set_updated_at();

-- ---------------------------------------------------------------- shipments
-- Anything that moves: MCF parcel, India parcel, production job, return, replacement.
create table if not exists ops.shipments (
  id                      uuid primary key default gen_random_uuid(),
  order_id                bigint not null references ops.orders(id),
  store                   text not null references ops.stores(id),
  seq                     int not null,                                -- P1, P2 ...
  kind                    text not null check (kind in ('mcf','india','make','return','replacement','unknown')),
  items                   jsonb not null default '[]',                 -- [{ "item_id": ..., "qty": ... }]
  step                    text not null check (step in (
                            'requested','print','cut','stitch','jobwork','received','qc','ready',
                            'packed','label','shipped','transit','out','delivered',
                            'on_way_back','blocked','exception','cancelled')),
  step_at                 timestamptz not null default now(),
  step_times              jsonb not null default '{}',
  responsible             text,
  responsible_since       timestamptz,
  due_at                  timestamptz,
  late                    boolean not null default false,
  block_reason            text,
  ship_to                 jsonb,
  carrier                 text,                                        -- text exactly as Shopify knows it
  service                 text,
  carrier_id              text references ops.carriers(id),
  service_id              text references ops.carrier_services(id),
  account_id              text references ops.shipping_accounts(id),
  tracking                text[] not null default '{}',                -- handy copy; truth is tracking_numbers
  mcf_id                  text unique,
  mcf_account             text,
  shopify_fulfillment_id  bigint unique,
  dispatch_file           text,
  gst_invoice_no          text unique,
  weight_kg               numeric(6,2),
  dims_cm                 text,
  cost                    numeric(12,2),
  eta                     date,
  delivered_at            timestamptz,
  last_scan_at            timestamptz,
  last_scan_place         text,
  last_scan_text          text,
  cities                  text[] not null default '{}',
  return_reason           text,
  return_outcome          text check (return_outcome in ('refund','replace','both')),
  linked_id               uuid references ops.shipments(id),
  created_by              text,
  created_at              timestamptz not null default now(),
  updated_at              timestamptz not null default now(),
  -- FLOWMERCE ADDITIONS for traceable migration from the Delayed Orders Tracker
  origin                  text not null default 'flowmerce' check (origin in ('flowmerce','shopify_sync','tracker_import')),
  kind_inferred           boolean not null default false               -- true when kind was guessed from the carrier name on import
);
create unique index if not exists shipments_seq on ops.shipments (order_id, seq);
create index if not exists shipments_carrier on ops.shipments (carrier_id);
create index if not exists shipments_open on ops.shipments (store, step, due_at) where step not in ('delivered','cancelled');
drop trigger if exists shipments_updated_at on ops.shipments;
create trigger shipments_updated_at before update on ops.shipments
  for each row execute function ops.set_updated_at();
comment on column ops.shipments.kind_inferred is 'Imported tracker rows do not say whether a parcel was MCF or India. true = kind was inferred from the carrier name and must be confirmed.';

-- ---------------------------------------------------------------- stock
create table if not exists ops.stock (
  store      text not null references ops.stores(id),
  sku        text not null,
  fba        int,
  india      int,
  shelf      text,
  make_open  int,
  as_of      timestamptz not null,
  primary key (store, sku)
);
comment on table ops.stock is 'Copied from the ERP every 15 minutes. Empty until ERP access exists (plan C7).';

-- ---------------------------------------------------------------- events
-- Everything that happened, once. The order timeline is just these rows.
create table if not exists ops.events (
  id            bigserial primary key,
  at            timestamptz not null default now(),
  store         text references ops.stores(id),
  order_id      bigint references ops.orders(id),
  shipment_id   uuid references ops.shipments(id),
  item_id       bigint references ops.items(id),
  type          text not null check (type in ('shopify','step','scan','note','action','alert','alert_update','system')),
  by            text not null,
  title         text not null,
  data          jsonb,
  external_id   text unique,                                          -- a repeat is refused
  parent_id     bigint references ops.events(id),
  alert_kind    text check (alert_kind in ('late','stuck','carrier','hold','changed_after_send','stock_short','blocked','system')),
  severity      text check (severity in ('red','amber')),
  level         int check (level in (1,2,3)),
  owner_team    text check (owner_team in ('production','shipment','orders','care')),
  assigned_to   text,
  reason        text,
  action        text,
  due_at        timestamptz,
  seen_at       timestamptz,
  escalated_at  timestamptz,
  closed_at     timestamptz,
  closed_by     text
);
create index if not exists events_order on ops.events (order_id, at);
create index if not exists events_shipment on ops.events (shipment_id, at);
create index if not exists events_open_alerts on ops.events (assigned_to, due_at) where type = 'alert' and closed_at is null;

-- ##################################################################### 030_ops_tracking.sql
-- =====================================================================================
-- Flowmerce central database · 030 · tracking and problems (the accuracy fix)
-- tracking_numbers · tracking_scans · shipping_exceptions · shipping_claims · return_cases
-- Safe to run more than once.
-- =====================================================================================

-- ---------------------------------------------------------------- tracking_numbers
-- THE TRUTH FOR TRACKING. One row per (carrier, tracking number).
create table if not exists ops.tracking_numbers (
  id               uuid primary key default gen_random_uuid(),
  shipment_id      uuid not null references ops.shipments(id),
  store            text not null references ops.stores(id),
  carrier_id       text not null references ops.carriers(id),
  service_id       text references ops.carrier_services(id),
  tracking_number  text not null,
  source           text not null check (source in ('shopify','amazon','aggregator','carrier_api','manual','tracker_import')),
  aggregator_id    text unique,
  status           text not null default 'pending' check (status in (
                     'pending','info_received','in_transit','out_for_delivery','delivered','exception','returned','expired')),
  status_detail    text,
  registered_at    timestamptz not null default now(),
  picked_up_at     timestamptz,
  last_scan_at     timestamptz,
  eta              date,
  promised_by      date,
  delivered_at     timestamptz,
  signed_by        text,
  pod_url          text,
  scan_count       int not null default 0,
  origin_country   text,
  dest_country     text,
  active           boolean not null default true,
  stopped_at       timestamptz,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  -- FLOWMERCE ADDITIONS: freshness and honesty, per tracking number
  last_checked_at     timestamptz,                                    -- last time we ASKED the source (success or not)
  last_check_ok_at    timestamptz,                                    -- last time the source answered correctly
  last_check_error    text,                                           -- last error from the source (no secrets)
  check_attempts      int not null default 0,                         -- failures in a row; reset on success
  delivery_confirmed  boolean not null default false,                 -- true ONLY when a source that can confirm delivery said delivered
  raw_status          text,                                           -- latest status exactly as the source wrote it
  -- team check, kept apart from carrier data so a person's mark never overwrites what the carrier said
  team_mark           text check (team_mark in ('delivered','lost','failed','in_transit','checked')),
  team_mark_by        text,
  team_mark_at        timestamptz,
  team_note           text,
  -- delivered must come with a time; a parcel is never "delivered" without one
  check (status <> 'delivered' or delivered_at is not null)
);
create unique index if not exists tracking_numbers_carrier_no on ops.tracking_numbers (carrier_id, tracking_number);
create index if not exists tracking_numbers_shipment on ops.tracking_numbers (shipment_id);
create index if not exists tracking_numbers_open on ops.tracking_numbers (status, last_scan_at) where active;
create index if not exists tracking_numbers_number on ops.tracking_numbers (tracking_number);
drop trigger if exists tracking_numbers_updated_at on ops.tracking_numbers;
create trigger tracking_numbers_updated_at before update on ops.tracking_numbers
  for each row execute function ops.set_updated_at();
comment on column ops.tracking_numbers.delivery_confirmed is 'Shopify-only "fulfilled" never sets this. Only amazon/aggregator/carrier_api delivered scans do.';

-- ---------------------------------------------------------------- tracking_scans
-- Every scan the source reports, in full. Never stored twice (external_id).
create table if not exists ops.tracking_scans (
  id           bigserial primary key,
  tracking_id  uuid not null references ops.tracking_numbers(id),
  shipment_id  uuid not null references ops.shipments(id),
  external_id  text not null unique,
  scanned_at   timestamptz not null,                                  -- carrier's clock (when it happened)
  received_at  timestamptz not null default now(),                    -- when we got it
  status       text not null check (status in (
                 'pending','info_received','in_transit','out_for_delivery','delivered','exception','returned','expired')),
  raw_status   text,
  message      text,
  city         text,
  province     text,
  country      text,
  source       text not null check (source in ('amazon','aggregator','carrier_api','shopify','tracker_import')),
  event_id     bigint references ops.events(id),
  raw          jsonb,
  -- FLOWMERCE ADDITION: which status_map rule produced `status` (null = not in the map -> pending)
  mapped_rule  text
);
create index if not exists tracking_scans_by_number on ops.tracking_scans (tracking_id, scanned_at desc);

-- ---------------------------------------------------------------- latest-status rule
-- The current status of a tracking number is the status of its NEWEST scan by scanned_at
-- (ties broken by received_at, then id), never "whatever arrived last". A late-arriving
-- older scan therefore cannot overwrite a newer one. This function recomputes one row.
create or replace function ops.recompute_tracking_status(p_tracking_id uuid) returns void
language plpgsql as $$
declare
  v_last ops.tracking_scans%rowtype;
  v_first_movement timestamptz;
  v_delivered timestamptz;
  v_confirm boolean;
begin
  select * into v_last
    from ops.tracking_scans
   where tracking_id = p_tracking_id
   order by scanned_at desc, received_at desc, id desc
   limit 1;
  if not found then
    return;                                    -- no scans: leave status as it is (pending by default)
  end if;

  select min(scanned_at) into v_first_movement
    from ops.tracking_scans
   where tracking_id = p_tracking_id and status in ('in_transit','out_for_delivery','delivered');

  select min(scanned_at) into v_delivered
    from ops.tracking_scans
   where tracking_id = p_tracking_id and status = 'delivered';

  v_confirm := v_last.status = 'delivered' and v_last.source in ('amazon','aggregator','carrier_api');

  update ops.tracking_numbers t set
    status             = v_last.status,
    status_detail      = v_last.message,
    raw_status         = v_last.raw_status,
    last_scan_at       = v_last.scanned_at,
    picked_up_at       = coalesce(t.picked_up_at, v_first_movement),
    delivered_at       = case when v_last.status = 'delivered' then coalesce(v_delivered, v_last.scanned_at) else null end,
    delivery_confirmed = v_confirm,
    scan_count         = (select count(*) from ops.tracking_scans s where s.tracking_id = p_tracking_id)
  where t.id = p_tracking_id;
end $$;
comment on function ops.recompute_tracking_status(uuid) is 'Derives tracking_numbers status from scans ordered by scanned_at. Call after inserting scans.';

-- ---------------------------------------------------------------- shipping_exceptions
create table if not exists ops.shipping_exceptions (
  id              uuid primary key default gen_random_uuid(),
  order_id        bigint not null references ops.orders(id),
  shipment_id     uuid not null references ops.shipments(id),
  tracking_id     uuid references ops.tracking_numbers(id),
  store           text not null references ops.stores(id),
  kind            text not null check (kind in ('delay','no_scan','damaged','lost','failed_delivery','address_issue','customs_hold','returned_to_sender','other')),
  severity        text not null default 'amber' check (severity in ('red','amber')),
  source          text not null check (source in ('carrier','job','person')),
  detected_at     timestamptz not null default now(),
  description     text,
  status          text not null default 'open' check (status in ('open','investigating','claim_filed','resolved','closed')),
  resolution      text,
  owner           text,
  alert_event_id  bigint references ops.events(id),
  resolved_at     timestamptz,
  closed_at       timestamptz
);
create index if not exists shipping_exceptions_shipment on ops.shipping_exceptions (shipment_id);
create index if not exists shipping_exceptions_open on ops.shipping_exceptions (status) where closed_at is null;
-- one OPEN exception of each kind per tracking number (stops the job raising duplicates)
create unique index if not exists shipping_exceptions_one_open
  on ops.shipping_exceptions (shipment_id, coalesce(tracking_id, '00000000-0000-0000-0000-000000000000'::uuid), kind)
  where closed_at is null;

-- ---------------------------------------------------------------- shipping_claims
create table if not exists ops.shipping_claims (
  id              uuid primary key default gen_random_uuid(),
  exception_id    uuid references ops.shipping_exceptions(id),
  shipment_id     uuid not null references ops.shipments(id),
  carrier_id      text not null references ops.carriers(id),
  store           text not null references ops.stores(id),
  claim_type      text not null check (claim_type in ('lost','damaged','late_delivery','overcharge')),
  claim_ref       text,
  amount_claimed  numeric(12,2),
  amount_paid     numeric(12,2),
  currency        text not null default 'USD',
  status          text not null default 'draft' check (status in ('draft','filed','accepted','rejected','paid')),
  filed_at        timestamptz,
  resolved_at     timestamptz,
  filed_by        text,
  note            text
);

-- ---------------------------------------------------------------- return_cases
create table if not exists ops.return_cases (
  id                    uuid primary key default gen_random_uuid(),
  order_id              bigint not null references ops.orders(id),
  store                 text not null references ops.stores(id),
  item_id               bigint references ops.items(id),
  qty                   int not null default 1 check (qty > 0),
  original_shipment_id  uuid references ops.shipments(id),
  return_shipment_id    uuid references ops.shipments(id),
  return_tracking_id    uuid references ops.tracking_numbers(id),
  case_type             text not null check (case_type in ('customer_return','rto','refused','undeliverable')),
  reason_code           text,
  reason                text,
  status                text not null default 'requested' check (status in ('requested','label_sent','on_way_back','received','inspected','closed')),
  condition             text check (condition in ('resellable','needs_repair','damaged')),
  outcome               text check (outcome in ('refund','replace','both','none')),
  restock_to            text,
  refund_amount         numeric(12,2),
  opened_by             text,
  opened_at             timestamptz not null default now(),
  received_at           timestamptz,
  closed_at             timestamptz
);
create index if not exists return_cases_order on ops.return_cases (order_id);

-- ##################################################################### 040_ops_costs_and_feeds.sql
-- =====================================================================================
-- Flowmerce central database · 040 · costs, rates, and data feeds
-- shipping_costs · rate_cards · webhook_inbox · sync_runs
-- Safe to run more than once.
-- NOTE: ops.sync_runs is a NEW table. The tracker's public.sync_runs is left untouched.
-- =====================================================================================

-- ---------------------------------------------------------------- shipping_costs
create table if not exists ops.shipping_costs (
  id           uuid primary key default gen_random_uuid(),
  shipment_id  uuid not null references ops.shipments(id),
  tracking_id  uuid references ops.tracking_numbers(id),
  store        text not null references ops.stores(id),
  kind         text not null check (kind in ('freight','fuel_surcharge','mcf_fee','remote_area','customs_duty','insurance','return_label','other')),
  amount       numeric(12,2) not null,
  currency     text not null default 'USD',
  amount_usd   numeric(12,2) not null,
  is_estimate  boolean not null default false,
  source       text not null check (source in ('carrier_invoice','amazon_report','rate_card','manual')),
  invoice_ref  text,
  billed_at    date,
  note         text,
  created_at   timestamptz not null default now()
);
create index if not exists shipping_costs_shipment on ops.shipping_costs (shipment_id);

-- ---------------------------------------------------------------- rate_cards
create table if not exists ops.rate_cards (
  id                  uuid primary key default gen_random_uuid(),
  carrier_id          text not null references ops.carriers(id),
  service_id          text not null references ops.carrier_services(id),
  origin_country      text not null,
  dest_country        text not null,
  zone                text,
  weight_from_kg      numeric(6,2) not null,
  weight_to_kg        numeric(6,2) not null,
  rate                numeric(12,2) not null,
  currency            text not null default 'USD',
  fuel_surcharge_pct  numeric(5,2) not null default 0,
  valid_from          date not null,
  valid_to            date,
  source              text not null default 'contract' check (source in ('contract','published','estimate')),
  active              boolean not null default true,
  check (weight_from_kg < weight_to_kg),
  check (valid_to is null or valid_from <= valid_to)
);
create index if not exists rate_cards_lookup on ops.rate_cards (carrier_id, service_id, dest_country, weight_from_kg) where active;

-- ---------------------------------------------------------------- webhook_inbox
-- Every incoming message, stored untouched BEFORE acting on it. Replayable.
-- Stays empty until a public HTTPS endpoint exists (plan C4 / decision D4).
create table if not exists ops.webhook_inbox (
  id            bigserial primary key,
  source        text not null check (source in ('shopify','amazon','aftership','17track','shiprocket','delhivery','dhl','fedex')),
  store         text references ops.stores(id),
  topic         text not null,
  external_id   text,
  received_at   timestamptz not null default now(),
  signature_ok  boolean not null,
  payload       jsonb not null,
  status        text not null default 'received' check (status in ('received','processed','failed','ignored')),
  attempts      int not null default 0,
  processed_at  timestamptz,
  error         text,
  event_id      bigint references ops.events(id)
);
create unique index if not exists webhook_inbox_once on ops.webhook_inbox (source, external_id);
create index if not exists webhook_inbox_todo on ops.webhook_inbox (status, received_at) where status in ('received','failed');

-- ---------------------------------------------------------------- sync_runs
-- Every load / check / poll. Powers "data freshness" on screen.
create table if not exists ops.sync_runs (
  id            bigserial primary key,
  source        text not null check (source in ('shopify','amazon','aftership','17track','shiprocket','delhivery','dhl','fedex','tracker_import','erp')),
  kind          text not null check (kind in ('backfill','nightly_check','poll','webhook_replay','import')),
  store         text references ops.stores(id),
  started_at    timestamptz not null default now(),
  finished_at   timestamptz,
  status        text not null default 'running' check (status in ('running','ok','partial','failed')),
  rows_read     int not null default 0,
  rows_written  int not null default 0,
  rows_failed   int not null default 0,
  cursor        text,
  error         text,
  triggered_by  text not null,
  -- FLOWMERCE ADDITION: a lock so the same feed never runs twice at once
  lock_key      text generated always as (case when status = 'running' then source || ':' || kind || ':' || coalesce(store,'*') end) stored
);
create index if not exists sync_runs_by_source on ops.sync_runs (source, started_at desc);
create unique index if not exists sync_runs_one_running on ops.sync_runs (lock_key) where lock_key is not null;
comment on column ops.sync_runs.lock_key is 'Only one running row per source/kind/store. A second start fails with a unique violation = duplicate run refused.';

-- ##################################################################### 060_ops_views.sql
-- =====================================================================================
-- Flowmerce central database · 060 · views (worked out live, never stored)
-- From the v2 design: stock_free · alert_board · daily · order_shipping_cost · carrier_performance
-- FLOWMERCE ADDITIONS: feed_freshness · shipment_diagnostics · shipping_summary
-- Safe to run more than once (create or replace).
-- =====================================================================================

-- ---------------------------------------------------------------- stock_free
create or replace view ops.stock_free as
select s.store, s.sku, s.fba, s.india,
  s.fba   - coalesce(r.fba, 0)   as fba_free,
  s.india - coalesce(r.india, 0) as india_free,
  s.as_of
from ops.stock s
left join (
  select sh.store, it.sku,
    sum(case when sh.kind = 'mcf'   then (x->>'qty')::int else 0 end) as fba,
    sum(case when sh.kind = 'india' then (x->>'qty')::int else 0 end) as india
  from ops.shipments sh
  cross join lateral jsonb_array_elements(sh.items) x
  join ops.items it on it.id = (x->>'item_id')::bigint
  where sh.step in ('requested','packed','label')
  group by sh.store, it.sku
) r using (store, sku);

-- ---------------------------------------------------------------- alert_board
create or replace view ops.alert_board as
select e.id, e.at as opened_at, e.alert_kind, e.severity, e.level, e.owner_team, e.assigned_to,
  e.reason, e.action, e.due_at, e.seen_at, o.store, o.name as order_name, sh.kind, sh.step, sh.responsible
from ops.events e
join ops.orders o on o.id = e.order_id
left join ops.shipments sh on sh.id = e.shipment_id
where e.type = 'alert' and e.closed_at is null;

-- ---------------------------------------------------------------- daily
create or replace view ops.daily as
select o.store, o.day,
  count(*) filter (where o.cancelled_at is null) as orders,
  sum(o.total - o.refunded_amount) filter (where o.cancelled_at is null) as sales,
  (select count(*) from ops.shipments sh
    where sh.store = o.store
      and ((sh.step_times->>'shipped')::timestamptz at time zone o.tz)::date = o.day) as shipped,
  count(*) filter (where o.late) as late_now
from (
  select x.*, st.timezone as tz, (x.placed_at at time zone st.timezone)::date as day
  from ops.orders x join ops.stores st on st.id = x.store
) o
group by o.store, o.tz, o.day;

-- ---------------------------------------------------------------- order_shipping_cost
create or replace view ops.order_shipping_cost as
select o.id as order_id, o.store, o.name as order_name, o.shipping_charged,
  coalesce(sum(c.amount_usd), 0) as cost_usd,
  coalesce(bool_or(c.is_estimate), false) as has_estimate,
  o.shipping_charged - coalesce(sum(c.amount_usd), 0) as margin_usd
from ops.orders o
left join ops.shipments sh on sh.order_id = o.id
left join ops.shipping_costs c on c.shipment_id = sh.id
group by o.id, o.store, o.name, o.shipping_charged;

-- ---------------------------------------------------------------- carrier_performance
create or replace view ops.carrier_performance as
select t.carrier_id, t.service_id, t.dest_country,
  -- picked_up_at is only known from a carrier feed; until then the dispatch (registration) time is used
  date_trunc('month', coalesce(t.picked_up_at, t.registered_at))::date as month,
  count(*) as shipments,
  count(*) filter (where t.status = 'delivered') as delivered,
  count(*) filter (where t.status = 'delivered' and t.delivery_confirmed) as delivered_confirmed,
  round(avg(extract(epoch from (t.delivered_at - coalesce(t.picked_up_at, t.registered_at))) / 86400)::numeric, 1) as avg_transit_days,
  round(100.0 * count(*) filter (where t.delivered_at::date <= t.promised_by)
        / nullif(count(*) filter (where t.status = 'delivered' and t.promised_by is not null), 0), 1) as on_time_pct,
  count(x.tracking_id) as with_problem
from ops.tracking_numbers t
left join (select tracking_id from ops.shipping_exceptions where tracking_id is not null group by tracking_id) x
  on x.tracking_id = t.id
group by t.carrier_id, t.service_id, t.dest_country, date_trunc('month', coalesce(t.picked_up_at, t.registered_at));

-- ---------------------------------------------------------------- feed_freshness  (ADDITION)
-- Latest attempt and latest success per feed. The UI shows "synced 12 min ago" from this,
-- and must show a warning when last_ok_at is old or last_status is failed.
create or replace view ops.feed_freshness as
select r.source, r.kind, r.store,
  max(r.started_at)                                   as last_attempt_at,
  max(r.finished_at) filter (where r.status = 'ok')   as last_ok_at,
  (array_agg(r.status order by r.started_at desc))[1] as last_status,
  (array_agg(r.error  order by r.started_at desc))[1] as last_error,
  count(*) filter (where r.status = 'failed' and r.started_at > now() - interval '24 hours') as failures_24h
from ops.sync_runs r
group by r.source, r.kind, r.store;

-- ---------------------------------------------------------------- shipment_diagnostics  (ADDITION)
-- One row per problem found. Thresholds come from ops.settings (step_limits.no_scan_h, default 72).
-- Never invents data: it only reports what is missing or contradictory.
create or replace view ops.shipment_diagnostics as
with lim as (
  select coalesce((select (value->>'no_scan_h')::int from ops.settings where key = 'step_limits'), 72) as no_scan_h
),
latest_scan as (
  select distinct on (s.tracking_id) s.tracking_id, s.status, s.scanned_at
  from ops.tracking_scans s
  order by s.tracking_id, s.scanned_at desc, s.received_at desc, s.id desc
)
-- 1. tracking number exists but no scan ever arrived
select t.store, t.shipment_id, t.id as tracking_id, t.tracking_number, 'no_scans'::text as problem, 'amber'::text as severity,
       'Tracking number registered ' || to_char(t.registered_at, 'YYYY-MM-DD') || ' but no scan received' as detail
from ops.tracking_numbers t, lim
where t.active and t.scan_count = 0 and t.registered_at < now() - make_interval(hours => lim.no_scan_h)
union all
-- 2. no movement for longer than the limit
select t.store, t.shipment_id, t.id, t.tracking_number, 'no_movement', 'red',
       'Last scan ' || to_char(t.last_scan_at, 'YYYY-MM-DD HH24:MI') || ' UTC'
from ops.tracking_numbers t, lim
where t.active and t.status not in ('delivered','returned','expired')
  and t.last_scan_at < now() - make_interval(hours => lim.no_scan_h)
union all
-- 3. shipment has no identified carrier
select sh.store, sh.id, null, null, 'missing_carrier', 'amber', coalesce('Carrier text: ' || sh.carrier, 'No carrier at all')
from ops.shipments sh
where sh.step in ('shipped','transit','out') and (sh.carrier_id is null or sh.carrier_id = 'unknown')
union all
-- 4. shown as delivered but no source that can confirm delivery has said so
select t.store, t.shipment_id, t.id, t.tracking_number, 'delivery_unconfirmed', 'amber',
       'Status delivered from source ' || t.source || ' (not carrier-confirmed)'
from ops.tracking_numbers t
where t.status = 'delivered' and not t.delivery_confirmed and t.delivered_at > now() - interval '30 days'
union all
-- 5. stored status disagrees with the newest scan
select t.store, t.shipment_id, t.id, t.tracking_number, 'status_mismatch', 'red',
       'Stored ' || t.status || ' but newest scan says ' || ls.status
from ops.tracking_numbers t join latest_scan ls on ls.tracking_id = t.id
where ls.status <> t.status
union all
-- 6. the source keeps failing for this number
select t.store, t.shipment_id, t.id, t.tracking_number, 'sync_failing', 'amber',
       t.check_attempts || ' failed checks; last error: ' || coalesce(t.last_check_error, '?')
from ops.tracking_numbers t
where t.active and t.check_attempts >= 3
union all
-- 7. the same tracking number is attached to more than one shipment
select min(t.store), null, null, t.tracking_number, 'duplicate_tracking', 'red',
       count(distinct t.shipment_id) || ' shipments share this number'
from ops.tracking_numbers t
group by t.tracking_number
having count(distinct t.shipment_id) > 1
union all
-- 8. shipped but no tracking number
select sh.store, sh.id, null, null, 'shipped_without_tracking', 'red', 'Step ' || sh.step || ' with no tracking number'
from ops.shipments sh
where sh.step in ('shipped','transit','out')
  and not exists (select 1 from ops.tracking_numbers t where t.shipment_id = sh.id)
union all
-- 9. delivery exception still open
select e.store, e.shipment_id, e.tracking_id, null, 'open_exception', e.severity,
       e.kind || ' since ' || to_char(e.detected_at, 'YYYY-MM-DD')
from ops.shipping_exceptions e
where e.closed_at is null
union all
-- 10. kind of an imported shipment was guessed and not yet confirmed
select sh.store, sh.id, null, null, 'kind_unconfirmed', 'amber', 'Imported; kind ' || sh.kind || ' inferred from carrier name'
from ops.shipments sh
where sh.kind_inferred;

-- ---------------------------------------------------------------- diagnostics_list / diagnostics_summary  (ADDITION)
create or replace view ops.diagnostics_list as
select d.*, o.id as order_id, o.name as order_name, sh.seq, sh.carrier_id
from ops.shipment_diagnostics d
left join ops.shipments sh on sh.id = d.shipment_id
left join ops.orders o on o.id = sh.order_id;

create or replace view ops.diagnostics_summary as
select store, problem, severity, count(*)::int as n
from ops.shipment_diagnostics
group by store, problem, severity;

-- ---------------------------------------------------------------- shipment_list  (ADDITION)
-- One row per tracking number with everything the Shipments screen shows. Filtered, sorted and
-- paged by the database (never loaded whole into the app). Age bands follow the tracker's rules:
-- days since dispatch, yellow 4 / orange 6 / red 9 (ops.settings.age_bands overrides).
create or replace view ops.shipment_list as
with bands as (
  select coalesce((select (value->>'yellow')::int from ops.settings where key = 'age_bands'), 4) as y,
         coalesce((select (value->>'orange')::int from ops.settings where key = 'age_bands'), 6) as o,
         coalesce((select (value->>'red')::int    from ops.settings where key = 'age_bands'), 9) as r,
         coalesce((select (value->>'no_scan_h')::int from ops.settings where key = 'step_limits'), 72) as no_scan_h
),
base as (
  select
    t.id as tracking_id, t.store, o.id as order_id, o.name as order_name, o.placed_at,
    sh.id as shipment_id, sh.seq, sh.kind, sh.kind_inferred, sh.step,
    t.carrier_id, c.name as carrier_name, t.tracking_number,
    replace(c.track_url, '{tracking}', t.tracking_number) as track_url,
    t.status, t.raw_status, t.status_detail, t.source, t.delivery_confirmed,
    t.registered_at as shipped_at, t.last_scan_at, sh.last_scan_place, t.delivered_at, t.eta,
    t.last_checked_at, t.last_check_ok_at, t.last_check_error, t.active,
    t.team_mark, t.team_mark_by, t.team_mark_at, t.team_note,
    floor(extract(epoch from (coalesce(t.delivered_at, now()) - t.registered_at)) / 86400)::int as days_since_dispatch,
    case when t.last_scan_at is not null
         then floor(extract(epoch from (now() - t.last_scan_at)) / 3600)::int end as hours_since_scan,
    (select count(*)::int from ops.shipping_exceptions e where e.tracking_id = t.id and e.closed_at is null) as open_exceptions
  from ops.tracking_numbers t
  join ops.shipments sh on sh.id = t.shipment_id
  join ops.orders o on o.id = sh.order_id
  left join ops.carriers c on c.id = t.carrier_id
)
select b.*,
  case
    when b.status = 'delivered' then 'delivered'
    when b.status in ('returned', 'expired') then 'closed'
    when b.days_since_dispatch >= bands.r then 'red'
    when b.days_since_dispatch >= bands.o then 'orange'
    when b.days_since_dispatch >= bands.y then 'yellow'
    else 'green'
  end as age_band,
  (b.active and b.last_scan_at is not null and b.hours_since_scan >= bands.no_scan_h) as no_movement,
  (b.status = 'pending' and b.active) as unverified
from base b cross join bands;

-- ---------------------------------------------------------------- shipping_summary  (ADDITION)
-- Small, fast numbers for the Home page. Never loads whole tables into the app.
create or replace view ops.shipping_summary as
select t.store,
  count(*) filter (where t.active)                                              as open_tracking,
  count(*) filter (where t.status = 'in_transit')                               as in_transit,
  count(*) filter (where t.status = 'out_for_delivery')                         as out_for_delivery,
  count(*) filter (where t.status = 'delivered' and t.delivered_at > now() - interval '30 days') as delivered_30d,
  count(*) filter (where t.status = 'delivered' and t.delivery_confirmed and t.delivered_at > now() - interval '30 days') as delivered_confirmed_30d,
  count(*) filter (where t.status = 'exception')                                as exceptions,
  count(*) filter (where t.status = 'pending' and t.active)                     as unverified,
  max(t.last_check_ok_at)                                                        as last_check_ok_at
from ops.tracking_numbers t
group by t.store;

-- ##################################################################### 070_seo_tables.sql
-- =====================================================================================
-- Flowmerce central database · 070 · SEO & Blog module (schema seo)
-- A 1:1 port of the SQLite schema in src/flowmerce/modules/seo/db.py (migrations 1 + 2).
-- Every table, column, unique rule and index is kept, so no SEO feature is lost.
--
-- Type changes (SQLite -> PostgreSQL), applied consistently:
--   INTEGER PRIMARY KEY      -> bigint generated by default as identity (old ids are kept on copy;
--                               the identity is moved past the highest id after loading)
--   0/1 INTEGER flags        -> boolean          (users.active, articles.shopify_published, automation_state.paused)
--   *_json TEXT              -> jsonb
--   ISO-8601 text timestamps -> timestamptz      (*_at, ts, source_timestamp, imported_at)
--   date text                -> date             (gsc/ga4 date, start_date, end_date, source_date)
--   REAL                     -> double precision
--   COLLATE NOCASE email     -> unique index on lower(email)
-- brand_id keeps its current values ('ridhi', 'cpc') and now references ops.stores.legacy_code.
-- Phase 4 ports the SEO Python SQL to these types; until then SEO keeps running on SQLite.
-- Safe to run more than once.
-- =====================================================================================

-- ---------------------------------------------------------------- users (local operator; merged with ops.people at Phase 5)
create table if not exists seo.users (
  id             bigint generated by default as identity primary key,
  email          text not null,
  name           text not null,
  role           text not null check (role in ('admin','seo_manager','reviewer')),
  password_hash  text not null,                                       -- obsolete in local-operator mode; kept, never exposed
  active         boolean not null default true,
  created_at     timestamptz not null,
  last_login_at  timestamptz
);
create unique index if not exists users_email_lower on seo.users (lower(email));

-- ---------------------------------------------------------------- sessions (obsolete, kept per "do not delete")
create table if not exists seo.sessions (
  id          text primary key,
  user_id     bigint not null references seo.users(id) on delete cascade,
  created_at  timestamptz not null,
  expires_at  timestamptz not null
);

-- ---------------------------------------------------------------- brand_settings
create table if not exists seo.brand_settings (
  brand_id       text primary key references ops.stores(legacy_code),
  settings_json  jsonb not null default '{}',
  updated_at     timestamptz,
  updated_by     bigint
);

-- ---------------------------------------------------------------- topics
create table if not exists seo.topics (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  title               text not null,
  primary_keyword     text not null,
  keyword_norm        text not null,
  secondary_keywords  text not null default '',
  intent              text not null default 'informational',
  search_volume       int,
  keyword_difficulty  int,
  volume_source       text,
  rationale           text not null default '',
  notes               text not null default '',
  validation_note     text not null default '',
  status              text not null default 'proposed',
  source              text not null default 'manual',
  owner_id            bigint,
  created_by          bigint,
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  source_updated_at   timestamptz,
  unique (brand_id, keyword_norm)
);

-- ---------------------------------------------------------------- keywords
create table if not exists seo.keywords (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  keyword             text not null,
  keyword_norm        text not null,
  search_volume       int,
  keyword_difficulty  int,
  intent              text,
  source_tool         text not null default 'manual',
  source_date         date,
  notes               text not null default '',
  source              text not null default 'manual',
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  unique (brand_id, keyword_norm)
);

-- ---------------------------------------------------------------- articles
create table if not exists seo.articles (
  id                  bigint generated by default as identity primary key,
  brand_id            text not null references ops.stores(legacy_code),
  topic_id            bigint references seo.topics(id) on delete set null,
  title               text not null,
  handle              text not null,
  primary_keyword     text not null default '',
  meta_title          text not null default '',
  meta_description    text not null default '',
  summary_html        text not null default '',
  body_html           text not null default '',
  tags                text not null default '',
  author              text not null default '',
  image_url           text not null default '',
  image_alt           text not null default '',
  status              text not null default 'draft',
  assignee_id         bigint references seo.users(id) on delete set null,
  version             int not null default 1,
  content_hash        text not null default '',
  approved_hash       text,
  approved_by         bigint,
  approved_at         timestamptz,
  review_note         text not null default '',
  shopify_blog_id     text,
  shopify_article_id  text,
  shopify_published   boolean not null default false,
  live_hash           text,
  live_url            text,
  publish_at          timestamptz,
  published_at        timestamptz,
  shopify_synced_at   timestamptz,
  origin              text not null default 'app',
  last_error          text,
  created_by          bigint,
  created_at          timestamptz not null,
  updated_at          timestamptz not null,
  unique (brand_id, handle)
);
create index if not exists articles_status on seo.articles (brand_id, status);
-- ADDITIONS (audit section 8.1 / 15: queries that run today without an index)
create index if not exists articles_topic on seo.articles (topic_id);
create index if not exists articles_shopify on seo.articles (brand_id, shopify_article_id);

-- ---------------------------------------------------------------- article_revisions
create table if not exists seo.article_revisions (
  id            bigint generated by default as identity primary key,
  article_id    bigint not null references seo.articles(id) on delete cascade,
  version       int not null,
