-- ##################################################################### 105_refresh_from_shopify_orders.sql
-- =====================================================================================
-- Flowmerce central database · 105 · refresh ops.* from the hub's public tables
--
-- Replaces 100_tracker_refresh.sql (removed). That version read the old "Delayed Orders Tracker" tables
-- (public.shipments with carrier_name, public.order_checks, public.manual_status), which do not
-- exist in this database, so every refresh failed. This version reads what the database really
-- has (checked 2026-11-17):
--   * public.stores                      -> ops.stores (missing rows only)
--   * public.orders                      -> ops.orders
--   * public.orders.raw -> fulfillments  -> ops.shipments (1 per Shopify fulfillment)
--                                           ops.tracking_numbers (1 per tracking number)
--                                           ops.tracking_scans (1 per Shopify shipment_status seen)
--   * public.sync_runs                   -> ops.sync_runs (the hub's Shopify runs, for freshness)
--   * ops.shopify_orders                 -> preferred over public.orders.raw for the same order: what
--                                           Flowmerce read straight from Shopify (carrier events, real
--                                           delivery time, ETA). Filled by the backend, keys stay in .env.
--
-- ops.refresh_from_shopify_orders() is REPEATABLE (the Flowmerce backend calls it every
-- 15 minutes and from "Refresh now"). It NEVER writes, updates or deletes anything in public.*.
--
-- Honesty rules:
--   * Shopify's word never confirms a delivery (delivery_confirmed stays false).
--   * Shopify fulfillments have no delivered time. When Shopify says "delivered", the time Shopify
--     last updated that fulfillment is used, and status_detail says so. With no such time the
--     parcel stays "pending"; it is never shown as delivered without a time.
--   * A fulfillment stored with only "createdAt" (no carrier, number or status: 5,051 such rows on
--     2026-11-17) is NOT turned into a shipment. It is counted as "incomplete" in the run result
--     until the hub re-fetches it from Shopify (see docs/shipping-schema-needs.md, G1).
--   * Unknown carrier names map to carrier "unknown", never guessed.
-- Safe to run more than once.
-- =====================================================================================

-- ---------------------------------------------------------------- reference words found in the live data
insert into ops.status_map (source, carrier_id, raw_status, status, is_terminal, confirms_delivery, note) values
  ('shopify','*','RETURNING_TO_SENDER', 'returned',   true,  false, 'Shopify shipment_status'),
  ('shopify','*','CARRIER_PICKED_UP',   'in_transit', false, false, null)
on conflict (source, carrier_id, raw_status) do nothing;

insert into ops.carrier_aliases (alias, carrier_id, note) values
  ('amazon shipping + amazon mcf', 'amazon_logistics_us', 'Shopify data (6)')
on conflict (alias) do nothing;

-- ---------------------------------------------------------------- what Flowmerce reads straight from Shopify
-- Written by the Flowmerce backend (modules/shipping/shopify_source.py) with the store keys from its own .env.
-- No Shopify keys or tokens are ever stored in Supabase. No customer details either: only the order
-- number, dates, statuses, carrier, tracking numbers and carrier events (time, status, city/country).
create table if not exists ops.shopify_orders (
  id                  bigint primary key,                   -- Shopify order id (legacy number)
  store               text not null references ops.stores(id),
  name                text not null,                        -- #RBP1234
  created_at          timestamptz not null,
  updated_at          timestamptz not null,                 -- Shopify's updatedAt (sync cursor)
  cancelled_at        timestamptz,
  fulfillment_status  text,                                 -- Shopify displayFulfillmentStatus
  fulfillments        jsonb not null default '[]',          -- normalised, see shopify_source.py
  fetched_at          timestamptz not null default now()
);
create index if not exists shopify_orders_store_updated on ops.shopify_orders (store, updated_at desc);
alter table ops.shopify_orders enable row level security;
comment on table ops.shopify_orders is 'Orders and fulfillments as Flowmerce last read them from the Shopify Admin API. Preferred over public.orders.raw by ops.refresh_from_shopify_orders().';
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant select, insert, update, delete on ops.shopify_orders to service_role';
  end if;
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant select, insert, update, delete on ops.shopify_orders to flowmerce_app';
  end if;
end $$;

-- The old tracker refresh cannot work against this database; remove it so nothing calls it by mistake.
drop function if exists ops.refresh_from_tracker(text);

create or replace function ops.refresh_from_shopify_orders(p_store text default null)
returns jsonb
language plpgsql
security invoker
set search_path = ops, pg_temp
as $$
declare
  v_run        bigint;
  n_orders     int := 0;
  n_fulfil     int := 0;
  n_direct     int := 0;
  n_incomplete int := 0;
  n_no_number  int := 0;
  n_new_ship   int := 0;
  n_upd_ship   int := 0;
  n_tracking   int := 0;
  n_scans      int := 0;
  n_exc        int := 0;
  n_hub_runs   int := 0;
  v_n          int;
begin
  -- Logged as source shopify / kind import. One running refresh at a time (unique lock_key on running
  -- rows): a second caller fails at once.
  insert into ops.sync_runs (source, kind, store, triggered_by)
  values ('shopify', 'import', p_store,
          coalesce(nullif(current_setting('request.jwt.claim.role', true), ''), current_user))
  returning id into v_run;

  -- ------------------------------------------------------------ 0. stores (add missing ones only)
  insert into ops.stores (id, name, shopify_domain, currency, timezone, active)
  select s.id, s.name, s.shopify_domain, s.currency, s.timezone, s.active
  from public.stores s
  where p_store is null or s.id = p_store
  on conflict do nothing;

  -- ------------------------------------------------------------ 1. orders
  -- a) from the hub (public.orders); never overwrites newer facts Flowmerce read from Shopify itself
  insert into ops.orders as o (id, store, name, placed_at, shop_updated_at, synced_at, origin,
                               cancelled_at, cancel_reason, financial_status, fulfillment_status,
                               currency, total, ship_country, stage, stage_at)
  --    When Flowmerce's own Shopify copy is at least as new, its cancelled/fulfillment status is used, so
  --    steps a) and b) never overwrite each other on every run.
  select p.id, p.store, p.name, p.placed_at, greatest(p.shop_updated_at, so.updated_at), now(), 'shopify_sync',
         case when so.id is not null then so.cancelled_at else p.cancelled_at end,
         p.cancel_reason, p.financial_status,
         case when so.id is not null then so.fulfillment_status else p.fulfillment_status end,
         coalesce(p.currency, 'USD'), p.total, p.ship_country,
         case when (case when so.id is not null then so.cancelled_at else p.cancelled_at end) is not null
              then 'cancelled' else p.stage end, p.stage_at
  from public.orders p
  join ops.stores s on s.id = p.store
  left join ops.shopify_orders so on so.id = p.id and so.updated_at >= p.shop_updated_at
  where p_store is null or p.store = p_store
  on conflict (id) do update set
    name               = excluded.name,
    shop_updated_at    = excluded.shop_updated_at,
    cancelled_at       = excluded.cancelled_at,
    cancel_reason      = excluded.cancel_reason,
    financial_status   = excluded.financial_status,
    fulfillment_status = excluded.fulfillment_status,
    currency           = excluded.currency,
    total              = excluded.total,
    ship_country       = excluded.ship_country,
    origin             = 'shopify_sync',
    synced_at          = now()
  where excluded.shop_updated_at >= o.shop_updated_at
    and (o.name, o.shop_updated_at, o.cancelled_at, o.financial_status, o.fulfillment_status, o.total,
         o.ship_country, o.origin)
        is distinct from
        (excluded.name, excluded.shop_updated_at, excluded.cancelled_at, excluded.financial_status,
         excluded.fulfillment_status, excluded.total, excluded.ship_country, excluded.origin);
  get diagnostics v_n = row_count;
  n_orders := v_n;

  -- b) read by Flowmerce straight from Shopify (ops.shopify_orders): newer facts win; orders the hub lacks are added
  insert into ops.orders as o (id, store, name, placed_at, shop_updated_at, synced_at, origin,
                               cancelled_at, fulfillment_status)
  select s.id, s.store, s.name, s.created_at, s.updated_at, now(), 'shopify_sync', s.cancelled_at, s.fulfillment_status
  from ops.shopify_orders s
  join ops.stores st on st.id = s.store
  where p_store is null or s.store = p_store
  on conflict (id) do update set
    shop_updated_at    = excluded.shop_updated_at,
    cancelled_at       = excluded.cancelled_at,
    fulfillment_status = excluded.fulfillment_status,
    synced_at          = now()
  where excluded.shop_updated_at > o.shop_updated_at
     or (excluded.shop_updated_at = o.shop_updated_at
         and (o.cancelled_at, o.fulfillment_status) is distinct from (excluded.cancelled_at, excluded.fulfillment_status));
  get diagnostics v_n = row_count;
  n_orders := n_orders + v_n;

  -- ------------------------------------------------------------ 2. staging: one row per Shopify fulfillment
  -- Orders Flowmerce read from Shopify itself use that data (carrier events, real delivery time, ETA);
  -- all other orders use the copy in the hub's public.orders.raw.
  create temp table _f on commit drop as
  select
    p.id                                                                          as order_id,
    p.store,
    p.synced_at                                                                   as order_synced_at,
    nullif(regexp_replace(coalesce(f.value->>'id', ''), '\D', '', 'g'), '')::bigint as fulfillment_id,
    (f.value ? 'status')                                                          as complete,
    lower(nullif(btrim(f.value->>'status'), ''))                                  as f_status,
    nullif(btrim(f.value->>'tracking_company'), '')                               as carrier_name,
    nullif(btrim(f.value->>'shipment_status'), '')                                as raw_status,
    upper(nullif(btrim(f.value->>'shipment_status'), ''))                         as raw_up,
    nullif(f.value->>'created_at', '')::timestamptz                               as created_at,
    nullif(f.value->>'updated_at', '')::timestamptz                               as updated_at,
    nullif(btrim(f.value->>'service'), '')                                        as service,
    coalesce((select jsonb_agg(jsonb_build_object('item_id', (li->>'id')::bigint, 'qty', (li->>'quantity')::int))
                from jsonb_array_elements(case when jsonb_typeof(f.value->'line_items') = 'array'
                                               then f.value->'line_items' else '[]'::jsonb end) li
               where li->>'id' ~ '^\d+$' and li->>'quantity' ~ '^\d+$'), '[]'::jsonb) as items,
    array(select distinct btrim(n)
            from jsonb_array_elements_text(
                   case when jsonb_typeof(f.value->'tracking_numbers') = 'array' then f.value->'tracking_numbers'
                        when nullif(btrim(f.value->>'tracking_number'), '') is not null
                          then jsonb_build_array(f.value->>'tracking_number')
                        else '[]'::jsonb end) n
           where nullif(btrim(n), '') is not null)                                as numbers,
    'hub'::text           as src,
    null::timestamptz     as eta,
    null::timestamptz     as delivered_src,
    null::timestamptz     as in_transit_at,
    '[]'::jsonb           as events,
    null::text    as carrier_id,
    null::text    as status,
    null::text    as mapped_rule,
    null::timestamptz as delivered_at,
    null::text    as note
  from public.orders p
  join ops.orders o on o.id = p.id
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(p.raw->'fulfillments') = 'array' then p.raw->'fulfillments' else '[]'::jsonb end) f(value)
  where (p_store is null or p.store = p_store)
    and not exists (select 1 from ops.shopify_orders s where s.id = p.id)
  union all
  select
    s.id, s.store, s.fetched_at,
    nullif(f.value->>'id', '')::bigint,
    true,
    lower(nullif(btrim(f.value->>'status'), '')),
    nullif(btrim(f.value->'tracking'->0->>'company'), ''),
    coalesce(case when hd.at is not null then 'DELIVERED' end, le.status, nullif(btrim(f.value->>'display_status'), '')),
    upper(coalesce(case when hd.at is not null then 'DELIVERED' end, le.status, nullif(btrim(f.value->>'display_status'), ''))),
    nullif(f.value->>'created_at', '')::timestamptz,
    nullif(f.value->>'updated_at', '')::timestamptz,
    nullif(btrim(f.value->>'service'), ''),
    case when jsonb_typeof(f.value->'items') = 'array' then f.value->'items' else '[]'::jsonb end,
    array(select distinct btrim(t->>'number')
            from jsonb_array_elements(case when jsonb_typeof(f.value->'tracking') = 'array'
                                           then f.value->'tracking' else '[]'::jsonb end) t
           where nullif(btrim(t->>'number'), '') is not null),
    'shopify',
    nullif(f.value->>'eta', '')::timestamptz,
    coalesce(nullif(f.value->>'delivered_at', '')::timestamptz, hd.at),
    nullif(f.value->>'in_transit_at', '')::timestamptz,
    case when jsonb_typeof(f.value->'events') = 'array' then f.value->'events' else '[]'::jsonb end,
    null, null, null, null, null
  from ops.shopify_orders s
  join ops.orders o on o.id = s.id
  cross join lateral jsonb_array_elements(
    case when jsonb_typeof(s.fulfillments) = 'array' then s.fulfillments else '[]'::jsonb end) f(value)
  -- the newest carrier event decides the status; without events, Shopify's display status does.
  -- Exception: once the carrier has scanned the parcel DELIVERED it stays delivered. Carriers (DHL above all) sometimes
  -- add a stray event days later, e.g. "FAILURE" with no text 18 days after delivery; Shopify keeps its delivery time
  -- and "marked as delivered" for such parcels, and so does Flowmerce.
  left join lateral (select e->>'status' as status
                       from jsonb_array_elements(case when jsonb_typeof(f.value->'events') = 'array'
                                                      then f.value->'events' else '[]'::jsonb end) e
                      where nullif(e->>'at', '') is not null and nullif(e->>'status', '') is not null
                      order by (upper(e->>'status') = 'DELIVERED') desc, (e->>'at')::timestamptz desc, e->>'id' desc
                      limit 1) le on true
  -- A delivered order is delivered, whichever copy says so. Flowmerce's own read can be older than the hub's: Shopify
  -- lets Flowmerce's keys read only orders up to 60 days old, so a parcel delivered just before (or after) that limit
  -- stays "in transit" in Flowmerce's copy forever (e.g. CPC #6948, DHL delivered 18 Nov, copy last read 18 Nov 04:57
  -- in transit, order 60 days old the next morning). When the hub's copy of the same fulfillment says delivered, the
  -- fulfillment is delivered, timed by the hub's last update of it unless Flowmerce has Shopify's own delivery time.
  left join lateral (select coalesce(nullif(hf->>'updated_at', '')::timestamptz, hp.shop_updated_at) as at
                       from public.orders hp
                       cross join lateral jsonb_array_elements(case when jsonb_typeof(hp.raw->'fulfillments') = 'array'
                                                                    then hp.raw->'fulfillments' else '[]'::jsonb end) hf
                      where hp.id = s.id
                        and upper(btrim(coalesce(hf->>'shipment_status', ''))) = 'DELIVERED'
                        and nullif(regexp_replace(coalesce(hf->>'id', ''), '\D', '', 'g'), '') = f.value->>'id'
                        -- a fulfilment Shopify cancelled stays cancelled (10 such on 19 Nov still read "delivered" in the hub)
                        and lower(coalesce(f.value->>'status', '')) not in ('cancelled', 'error', 'failure')
                      limit 1) hd on true
  where p_store is null or s.store = p_store;

  select count(*) filter (where not complete or fulfillment_id is null) into n_incomplete from _f;
  delete from _f where not complete or fulfillment_id is null;
  select count(*), count(*) filter (where src = 'shopify') into n_fulfil, n_direct from _f;

  -- carrier: through the alias list; unmatched (blank, "Other", new names) -> unknown
  update _f t set carrier_id = a.carrier_id
    from ops.carrier_aliases a
   where a.alias = lower(coalesce(t.carrier_name, ''));
  update _f set carrier_id = 'unknown' where carrier_id is null;

  -- status: through the status map; no word = no carrier evidence yet = pending
  update _f t set status = m.status, mapped_rule = 'shopify/*/' || m.raw_status
    from ops.status_map m
   where m.source = 'shopify' and m.carrier_id = '*' and m.raw_status = t.raw_up;
  update _f set status = 'pending',
                note = 'Shopify status word not in the status map: ' || raw_status
   where status is null and raw_status is not null;
  update _f set status = 'pending' where status is null;

  -- delivered time: Shopify's own delivery time, else the newest "delivered" carrier event,
  -- else (hub data only) Shopify's last update of the fulfillment. Never carrier-confirmed.
  update _f set delivered_at = coalesce(delivered_src,
                  (select max((e->>'at')::timestamptz) from jsonb_array_elements(events) e
                    where upper(e->>'status') = 'DELIVERED' and nullif(e->>'at', '') is not null)),
                note = 'Delivered per Shopify carrier tracking (not carrier-confirmed)'
   where status = 'delivered' and src = 'shopify';
  update _f set delivered_at = updated_at,
                note = 'Delivered per Shopify; time is when Shopify last updated the fulfillment (not carrier-confirmed)'
   where status = 'delivered' and src = 'hub' and updated_at is not null;
  update _f set status = 'pending', note = 'Shopify said delivered but gave no time'
   where status = 'delivered' and delivered_at is null;

  -- ------------------------------------------------------------ 3. shipments (one per Shopify fulfillment)
  create temp table _s on commit drop as
  select f.*,
    case
      when f.f_status in ('cancelled', 'error', 'failure') then 'cancelled'
      when f.status = 'delivered'                         then 'delivered'
      when f.status in ('exception', 'returned')          then 'exception'
      when f.status = 'out_for_delivery'                  then 'out'
      when f.status = 'in_transit'                        then 'transit'
      else 'shipped'
    end as step
  from _f f;

  create temp table _chg on commit drop as
  select sh.id as shipment_id, sh.order_id, sh.seq, sh.step as old_step, s.step as new_step,
         coalesce(s.delivered_at, s.updated_at, now()) as at
  from ops.shipments sh join _s s on s.fulfillment_id = sh.shopify_fulfillment_id
  where sh.origin = 'shopify_sync' and sh.step <> s.step;

  update ops.shipments sh set
    step         = s.step,
    step_at      = case when sh.step <> s.step then coalesce(s.delivered_at, s.updated_at, now()) else sh.step_at end,
    step_times   = sh.step_times || jsonb_strip_nulls(jsonb_build_object('shipped', s.created_at,
                                                                         'transit', s.in_transit_at,
                                                                         'delivered', s.delivered_at)),
    carrier      = s.carrier_name,
    carrier_id   = s.carrier_id,
    service      = s.service,
    eta          = s.eta::date,
    delivered_at = s.delivered_at,
    tracking     = s.numbers,
    items        = case when s.items <> '[]'::jsonb then s.items else sh.items end
  from _s s
  where sh.shopify_fulfillment_id = s.fulfillment_id
    and sh.origin = 'shopify_sync'
    and (sh.step, sh.carrier, sh.carrier_id, sh.service, sh.eta, sh.delivered_at, sh.tracking,
         case when s.items <> '[]'::jsonb then s.items else sh.items end)
        is distinct from
        (s.step, s.carrier_name, s.carrier_id, s.service, s.eta::date, s.delivered_at, s.numbers, sh.items);
  get diagnostics n_upd_ship = row_count;

  insert into ops.shipments (order_id, store, seq, kind, kind_inferred, items, step, step_at, step_times,
                             carrier, service, carrier_id, shopify_fulfillment_id, eta, delivered_at, tracking,
                             origin, created_by)
  select s.order_id, s.store,
    coalesce((select max(x.seq) from ops.shipments x where x.order_id = s.order_id), 0)
      + row_number() over (partition by s.order_id order by s.created_at nulls last, s.fulfillment_id),
    case when s.service = 'amazon-fulfillment'                   then 'mcf'
         when s.carrier_id = 'amazon_logistics_us'               then 'mcf'
         when s.carrier_id in ('dhl', 'fedex', 'dhl_ecommerce')  then 'india'
         else 'unknown' end,
    s.service is distinct from 'amazon-fulfillment',   -- only Amazon's own fulfillment service says MCF for sure
    s.items, s.step,
    coalesce(s.delivered_at, s.updated_at, s.created_at, now()),
    jsonb_strip_nulls(jsonb_build_object('shipped', s.created_at, 'transit', s.in_transit_at,
                                         'delivered', s.delivered_at)),
    s.carrier_name, s.service, s.carrier_id, s.fulfillment_id, s.eta::date, s.delivered_at, s.numbers,
    'shopify_sync', 'job:shopify_orders_refresh'
  from _s s
  where not exists (select 1 from ops.shipments x where x.shopify_fulfillment_id = s.fulfillment_id);
  get diagnostics n_new_ship = row_count;

  insert into ops.events (at, store, order_id, shipment_id, type, by, title, data, external_id)
  select c.at, sh.store, c.order_id, c.shipment_id, 'step', 'job:shopify_orders_refresh',
         'P' || c.seq || ': ' || c.old_step || ' → ' || c.new_step,
         jsonb_build_object('before', c.old_step, 'after', c.new_step),
         'step:' || c.shipment_id || ':' || c.new_step || ':' || extract(epoch from c.at)::bigint
  from _chg c join ops.shipments sh on sh.id = c.shipment_id
  on conflict (external_id) do nothing;

  -- ------------------------------------------------------------ 4. tracking numbers
  select count(*) into n_no_number from _s where step <> 'cancelled' and cardinality(numbers) = 0;

  -- one row per (carrier, number): a number on several fulfillments belongs to the newest live one
  create temp table _n on commit drop as
  select distinct on (s.carrier_id, n.num) s.*, n.num as tracking_number, sh.id as shipment_id
  from _s s
  cross join lateral unnest(s.numbers) n(num)
  join ops.shipments sh on sh.shopify_fulfillment_id = s.fulfillment_id
  where s.step <> 'cancelled'
  order by s.carrier_id, n.num, s.created_at desc nulls last, s.fulfillment_id desc;

  insert into ops.tracking_numbers as tn (
    shipment_id, store, carrier_id, tracking_number, source, status, status_detail, raw_status,
    registered_at, picked_up_at, eta, delivered_at, delivery_confirmed, dest_country,
    last_checked_at, last_check_ok_at, check_attempts, active, stopped_at)
  select n.shipment_id, n.store, n.carrier_id, n.tracking_number, 'shopify', n.status, n.note, n.raw_status,
    coalesce(n.created_at, now()), n.in_transit_at, n.eta::date, n.delivered_at,
    false,                                            -- Shopify's word never confirms a delivery
    o.ship_country,
    n.order_synced_at, n.order_synced_at, 0,
    n.status not in ('delivered', 'returned', 'expired'),
    case when n.status in ('delivered', 'returned', 'expired') then now() end
  from _n n join ops.orders o on o.id = n.order_id
  on conflict (carrier_id, tracking_number) do update set
    shipment_id      = excluded.shipment_id,
    status           = excluded.status,
    status_detail    = excluded.status_detail,
    raw_status       = excluded.raw_status,
    picked_up_at     = coalesce(excluded.picked_up_at, tn.picked_up_at),
    eta              = excluded.eta,
    delivered_at     = excluded.delivered_at,
    dest_country     = excluded.dest_country,
    last_checked_at  = excluded.last_checked_at,
    last_check_ok_at = excluded.last_check_ok_at,
    active           = excluded.active,
    stopped_at       = case when not excluded.active then coalesce(tn.stopped_at, now()) end
  where tn.source = 'shopify'
    and (tn.shipment_id, tn.status, tn.raw_status, tn.delivered_at, tn.status_detail, tn.dest_country,
         tn.last_checked_at, tn.active, tn.eta, coalesce(excluded.picked_up_at, tn.picked_up_at))
        is distinct from
        (excluded.shipment_id, excluded.status, excluded.raw_status, excluded.delivered_at, excluded.status_detail,
         excluded.dest_country, excluded.last_checked_at, excluded.active, excluded.eta, tn.picked_up_at);
  get diagnostics n_tracking = row_count;

  -- numbers whose fulfillment was cancelled stop being tracked
  update ops.tracking_numbers tn set active = false, stopped_at = coalesce(tn.stopped_at, now())
    from ops.shipments sh
   where sh.id = tn.shipment_id and sh.step = 'cancelled' and tn.active and tn.source = 'shopify';

  -- ------------------------------------------------------------ 5. scans
  -- Direct Shopify data: one scan per real carrier event (time, place, message), per tracking number.
  -- Hub data: Shopify keeps only the current status word, so each new word becomes one scan row timed by
  -- Shopify's update of the fulfillment. Once a number has real events, those placeholder rows are removed
  -- so the newest scan is always a real carrier event.
  with gone as (
    delete from ops.tracking_scans sc
     using _n n, ops.tracking_numbers tn
     where n.src = 'shopify' and jsonb_array_length(n.events) > 0
       and tn.carrier_id = n.carrier_id and tn.tracking_number = n.tracking_number
       and sc.tracking_id = tn.id and sc.external_id like 'shopify:%'
    returning sc.external_id
  )
  delete from ops.events e using gone where e.external_id = gone.external_id;   -- and their timeline lines

  create temp table _ins (id bigint, tracking_id uuid, shipment_id uuid, external_id text,
                          scanned_at timestamptz, status text, raw_status text, city text) on commit drop;
  with ins as (
    insert into ops.tracking_scans (tracking_id, shipment_id, external_id, scanned_at, status, raw_status,
                                    message, city, province, country, source, mapped_rule)
    select tn.id, tn.shipment_id,
      'shopify_event:' || (e->>'id') || ':' || n.tracking_number,
      (e->>'at')::timestamptz, coalesce(m.status, 'pending'), e->>'status',
      coalesce(nullif(btrim(e->>'message'), ''), 'Carrier event: ' || (e->>'status')),
      nullif(btrim(e->>'city'), ''), nullif(btrim(e->>'province'), ''), nullif(btrim(e->>'country'), ''),
      'shopify', case when m.status is not null then 'shopify/*/' || m.raw_status end
    from _n n
    join ops.tracking_numbers tn on tn.carrier_id = n.carrier_id and tn.tracking_number = n.tracking_number
    cross join lateral jsonb_array_elements(n.events) e
    left join ops.status_map m on m.source = 'shopify' and m.carrier_id = '*' and m.raw_status = upper(e->>'status')
    where n.src = 'shopify' and tn.source = 'shopify'
      and nullif(e->>'id', '') is not null and nullif(e->>'at', '') is not null and nullif(e->>'status', '') is not null
    union all
    select tn.id, tn.shipment_id,
      'shopify:' || n.carrier_id || ':' || n.tracking_number || ':' || n.raw_up,
      n.updated_at, n.status, n.raw_status, 'Shopify shipment status: ' || n.raw_status,
      null, null, null, 'shopify', n.mapped_rule
    from _n n
    join ops.tracking_numbers tn on tn.carrier_id = n.carrier_id and tn.tracking_number = n.tracking_number
    where n.src = 'hub' and n.raw_status is not null and n.updated_at is not null and tn.source = 'shopify'
      and n.status = tn.status                    -- never a scan that disagrees with the stored status
    on conflict (external_id) do nothing
    returning id, tracking_id, shipment_id, external_id, scanned_at, status, raw_status, city
  )
  insert into _ins select * from ins;
  get diagnostics n_scans = row_count;

  -- timeline: every status change, but only the first of a run of "in transit" hops
  insert into ops.events (at, store, order_id, shipment_id, type, by, title, data, external_id)
  select i.scanned_at, sh.store, sh.order_id, i.shipment_id, 'scan', 'shopify',
         initcap(replace(i.status, '_', ' ')) || coalesce(' · ' || i.city, '') || ' (Shopify)',
         jsonb_build_object('raw_status', i.raw_status, 'tracking_id', i.tracking_id),
         i.external_id
  from _ins i join ops.shipments sh on sh.id = i.shipment_id
  where i.status <> 'in_transit'
     or not exists (select 1 from ops.tracking_scans p
                     where p.tracking_id = i.tracking_id and p.status = 'in_transit' and p.scanned_at < i.scanned_at)
  on conflict (external_id) do nothing;

  update ops.tracking_scans s set event_id = e.id
    from _ins i join ops.events e on e.external_id = i.external_id
   where s.id = i.id and s.event_id is null;

  update ops.tracking_numbers tn set
    scan_count   = c.n,
    last_scan_at = c.last_at,
    picked_up_at = coalesce(tn.picked_up_at, c.first_move)
  from (select tracking_id, count(*)::int as n, max(scanned_at) as last_at,
               min(scanned_at) filter (where status in ('in_transit', 'out_for_delivery', 'delivered')) as first_move
          from ops.tracking_scans group by tracking_id) c
  where c.tracking_id = tn.id
    and (tn.scan_count, tn.last_scan_at, tn.picked_up_at)
        is distinct from (c.n, c.last_at, coalesce(tn.picked_up_at, c.first_move));

  update ops.shipments sh set last_scan_at = x.last_at, last_scan_place = x.place, last_scan_text = x.msg
  from (select distinct on (s.shipment_id) s.shipment_id, s.scanned_at as last_at, s.message as msg,
               nullif(concat_ws(', ', s.city, s.province, s.country), '') as place
          from ops.tracking_scans s order by s.shipment_id, s.scanned_at desc, s.id desc) x
  where x.shipment_id = sh.id
    and (sh.last_scan_at, sh.last_scan_place, sh.last_scan_text) is distinct from (x.last_at, x.place, x.msg);

  -- ------------------------------------------------------------ 6. exceptions from Shopify's carrier status
  insert into ops.shipping_exceptions (order_id, shipment_id, tracking_id, store, kind, severity, source,
                                       detected_at, description, status)
  select sh.order_id, tn.shipment_id, tn.id, tn.store, k.kind, k.severity, 'carrier',
         coalesce(tn.last_scan_at, now()), 'Shopify reports ' || coalesce(tn.raw_status, 'a delivery problem'), 'open'
  from ops.tracking_numbers tn
  join ops.shipments sh on sh.id = tn.shipment_id
  cross join lateral (select
      case upper(coalesce(tn.raw_status, ''))
        when 'DELAYED'             then 'delay'
        when 'RETURNED'            then 'returned_to_sender'
        when 'RETURN_TO_SENDER'    then 'returned_to_sender'
        when 'RETURNING_TO_SENDER' then 'returned_to_sender'
        else 'failed_delivery' end as kind,
      case upper(coalesce(tn.raw_status, ''))
        when 'DELAYED'             then 'amber'
        when 'ATTEMPTED_DELIVERY'  then 'amber'
        else 'red' end as severity) k
  where tn.source = 'shopify' and tn.status in ('exception', 'returned')
    and not exists (select 1 from ops.shipping_exceptions e
                     where e.tracking_id = tn.id and e.kind = k.kind and e.closed_at is null);
  get diagnostics n_exc = row_count;

  -- carrier-raised problems close themselves once the parcel moves on (in transit again, out, delivered)
  update ops.shipping_exceptions e set
    status = 'resolved', resolved_at = now(), closed_at = now(),
    resolution = case when tn.status = 'delivered' then 'Shopify later reported delivered'
                      else 'Carrier tracking moved on: ' || tn.status end
  from ops.tracking_numbers tn
  where e.tracking_id = tn.id and e.source = 'carrier' and e.closed_at is null
    and tn.status in ('delivered', 'in_transit', 'out_for_delivery');

  -- ------------------------------------------------------------ 7. order stage from its shipments
  -- No shipments yet: keep the hub's own stage (checked, routed, in_production, packed, on_hold ...).
  update ops.orders o set
    stage     = x.stage,
    stage_at  = now(),
    closed_at = case when x.stage = 'delivered' then coalesce(o.closed_at, x.last_delivered, now()) end
  from (
    select o2.id,
      max(sh.delivered_at) as last_delivered,
      case
        when o2.cancelled_at is not null then 'cancelled'
        when count(sh.id) filter (where sh.step <> 'cancelled') = 0 then
          coalesce((select p.stage from public.orders p where p.id = o2.id), o2.stage, 'new')
        when bool_and(sh.step = 'delivered') filter (where sh.step <> 'cancelled')
             and upper(coalesce(o2.fulfillment_status, '')) <> 'PARTIALLY_FULFILLED' then 'delivered'
        when bool_or(sh.step in ('transit', 'out', 'exception')) then 'transit'
        else 'shipped'
      end as stage
    from ops.orders o2
    left join ops.shipments sh on sh.order_id = o2.id
    where o2.origin = 'shopify_sync' and (p_store is null or o2.store = p_store)
    group by o2.id
  ) x
  where o.id = x.id and o.stage is distinct from x.stage;

  -- ------------------------------------------------------------ 8. mirror the hub's sync runs (freshness)
  insert into ops.sync_runs (source, kind, store, started_at, finished_at, status, rows_read, rows_written,
                             rows_failed, error, triggered_by, cursor)
  select r.source, r.kind, r.store, r.started_at, r.finished_at, r.status,
         coalesce(r.rows_read, 0), coalesce(r.rows_written, 0), coalesce(r.rows_failed, 0),
         nullif(left(r.error, 1000), ''), 'hub:' || coalesce(r.triggered_by, '?'), 'hub_run:' || r.id
  from public.sync_runs r
  where r.status in ('ok', 'partial', 'failed')
    and r.source in ('shopify','amazon','aftership','17track','shiprocket','delhivery','dhl','fedex','erp')
    and r.kind in ('backfill','nightly_check','webhook_replay')
    and r.started_at > now() - interval '30 days'
    and (p_store is null or r.store = p_store or r.store is null)
    and (r.store is null or exists (select 1 from ops.stores s where s.id = r.store))
    and not exists (select 1 from ops.sync_runs x where x.cursor = 'hub_run:' || r.id);
  get diagnostics n_hub_runs = row_count;

  -- ------------------------------------------------------------ 9. close the run log
  update ops.sync_runs set
    finished_at  = clock_timestamp(),
    status       = 'ok',
    rows_read    = n_fulfil + n_incomplete,
    rows_written = n_new_ship + n_upd_ship + n_tracking + n_scans,
    rows_failed  = n_incomplete
  where id = v_run;

  return jsonb_build_object(
    'run_id', v_run, 'orders_changed', n_orders, 'fulfillments', n_fulfil,
    'fulfillments_from_shopify', n_direct,
    'fulfillments_incomplete', n_incomplete, 'shipped_without_number', n_no_number,
    'shipments_new', n_new_ship, 'shipments_updated', n_upd_ship, 'tracking_changed', n_tracking,
    'new_scans', n_scans, 'exceptions_opened', n_exc, 'hub_runs_copied', n_hub_runs);
end $$;

comment on function ops.refresh_from_shopify_orders(text) is
  'Repeatable refresh of ops.* from public.orders (Shopify fulfillments in raw) and public.sync_runs. Never writes to public.*.';

-- ---------------------------------------------------------------- team marks made in Flowmerce
create or replace function ops.set_team_mark(p_tracking_id uuid, p_mark text, p_note text, p_by text)
returns jsonb
language plpgsql
security invoker
set search_path = ops, pg_temp
as $$
declare
  v_ship uuid;
  v_order bigint;
  v_store text;
  v_kind text;
begin
  if p_mark is not null and p_mark not in ('delivered', 'lost', 'failed', 'in_transit', 'checked') then
    raise exception 'Unknown team mark %', p_mark using errcode = '22023';
  end if;
  if p_mark is null and nullif(btrim(coalesce(p_note, '')), '') is null then
    raise exception 'A mark or a note is required' using errcode = '22023';
  end if;
  if nullif(btrim(coalesce(p_by, '')), '') is null then
    raise exception 'Who made the mark is required' using errcode = '22023';
  end if;

  update ops.tracking_numbers set
    team_mark    = coalesce(p_mark, team_mark),
    team_mark_by = p_by,
    team_mark_at = now(),
    team_note    = coalesce(nullif(btrim(coalesce(p_note, '')), ''), team_note)
  where id = p_tracking_id
  returning shipment_id, store into v_ship, v_store;
  if not found then
    raise exception 'Tracking number not found' using errcode = 'P0002';
  end if;
  select order_id into v_order from ops.shipments where id = v_ship;

  insert into ops.events (store, order_id, shipment_id, type, by, title, data)
  values (v_store, v_order, v_ship, 'note', p_by,
          case when p_mark is not null then 'Team marked ' || p_mark else 'Team note' end,
          jsonb_strip_nulls(jsonb_build_object('mark', p_mark, 'note', nullif(btrim(coalesce(p_note, '')), ''),
                                               'tracking_id', p_tracking_id)));

  if p_mark in ('lost', 'failed') then
    v_kind := case p_mark when 'lost' then 'lost' else 'failed_delivery' end;
    insert into ops.shipping_exceptions (order_id, shipment_id, tracking_id, store, kind, severity, source,
                                         description, status, owner)
    select v_order, v_ship, p_tracking_id, v_store, v_kind, 'red', 'person',
           coalesce(nullif(btrim(coalesce(p_note, '')), ''), 'Team marked ' || p_mark), 'open', p_by
    where not exists (select 1 from ops.shipping_exceptions e
                       where e.tracking_id = p_tracking_id and e.kind = v_kind and e.closed_at is null);
  end if;

  return jsonb_build_object('ok', true, 'tracking_id', p_tracking_id, 'mark', p_mark);
end $$;

comment on function ops.set_team_mark(uuid, text, text, text) is
  'A person''s check on a parcel. Kept apart from the carrier status; lost/failed opens an exception.';

-- ---------------------------------------------------------------- who may call these
revoke execute on function ops.refresh_from_shopify_orders(text) from public;
revoke execute on function ops.set_team_mark(uuid, text, text, text) from public;
do $$
begin
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke execute on function ops.refresh_from_shopify_orders(text) from anon, authenticated';
    execute 'revoke execute on function ops.set_team_mark(uuid, text, text, text) from anon, authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant execute on function ops.refresh_from_shopify_orders(text) to service_role';
    execute 'grant execute on function ops.set_team_mark(uuid, text, text, text) to service_role';
  end if;
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant execute on function ops.refresh_from_shopify_orders(text) to flowmerce_app';
    execute 'grant execute on function ops.set_team_mark(uuid, text, text, text) to flowmerce_app';
    execute 'grant usage on schema public to flowmerce_app';
    execute 'grant select on public.orders, public.stores, public.sync_runs to flowmerce_app';
  end if;
end $$;

-- Tell the Supabase API about the new function right away.
notify pgrst, 'reload schema';

-- ##################################################################### 106_service_role_timeout.sql
-- 106: give Flowmerce's server key enough time for the Shipping merge.
--
-- Supabase stops API calls after a few seconds by default. ops.refresh_from_shopify_orders() re-checks every
-- order Flowmerce knows about (about 5,000 orders and 45,000 carrier events today), which takes longer than that,
-- especially the first time. This raises the limit for the service_role (the server-only secret key) only.
-- The browser keys (anon, authenticated) keep Supabase's short limits.
-- Safe to run more than once.

alter role service_role set statement_timeout = '3min';
notify pgrst, 'reload config';

-- ##################################################################### 107_flow_board.sql
-- 107: one row per parcel (or open order) for the Shipping page.  Read-only view; safe to run more than once.
--
-- Three kinds of row:
--   tracking  every tracking number Flowmerce knows (ops.shipment_list), delivered ones included
--   shipment  a fulfilment that has no tracking number yet (dispatched without a number)
--   order     an order placed in the last 60 days that is not cancelled and has no fulfilment yet (not dispatched)
--
-- Each row carries the order's value, payment state and cancel time (ops.orders), and from the hub's order copy
-- (public.orders.raw) only the destination CITY and STATE and a yes/no "the order note says DONE".
-- The note text, names, street addresses, e-mails and phone numbers are never selected.

create or replace view ops.flow_board with (security_invoker = true) as
with hub as (
  select p.id,
         nullif(coalesce(p.raw->'shippingAddress'->>'city', p.raw->'shipping_address'->>'city'), '')               as ship_city,
         nullif(coalesce(p.raw->'shippingAddress'->>'provinceCode', p.raw->'shipping_address'->>'province_code'), '') as ship_state,
         coalesce(p.raw->>'note', '') ~* '\mdone\M'                                                                   as note_done
  from public.orders p
)
select 'tracking'::text                 as row_kind,
       t.tracking_id::text              as row_id,
       t.tracking_id,
       t.store, t.order_id, t.order_name, t.placed_at,
       t.shipment_id, t.kind,
       t.carrier_name, t.tracking_number, t.track_url,
       t.status, t.raw_status, t.source,
       t.shipped_at, t.last_scan_at, t.last_scan_place, sh.last_scan_text,
       t.delivered_at, t.eta, t.last_check_ok_at,
       t.team_mark, t.team_mark_at,
       t.open_exceptions,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false) as note_done
from ops.shipment_list t
join ops.shipments sh on sh.id = t.shipment_id
join ops.orders o     on o.id  = t.order_id
left join hub h       on h.id  = t.order_id

union all

select 'shipment', sh.id::text, null::uuid,
       sh.store, o.id, o.name, o.placed_at,
       sh.id, sh.kind,
       coalesce(c.name, nullif(sh.carrier, '')), null::text, null::text,
       'pending'::text, null::text, 'shopify'::text,
       sh.created_at, null::timestamptz, sh.last_scan_place, sh.last_scan_text,
       sh.delivered_at, sh.eta, null::timestamptz,
       null::text, null::timestamptz,
       0,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false)
from ops.shipments sh
join ops.orders o on o.id = sh.order_id
left join ops.carriers c on c.id = sh.carrier_id
left join hub h on h.id = o.id
where sh.step not in ('cancelled')
  and not exists (select 1 from ops.tracking_numbers t where t.shipment_id = sh.id)

union all

select 'order', o.id::text, null::uuid,
       o.store, o.id, o.name, o.placed_at,
       null::uuid, null::text,
       null::text, null::text, null::text,
       null::text, null::text, null::text,
       null::timestamptz, null::timestamptz, null::text, null::text,
       null::timestamptz, null::date, null::timestamptz,
       null::text, null::timestamptz,
       0,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false)
from ops.orders o
left join hub h on h.id = o.id
where o.placed_at > now() - interval '60 days'
  and o.cancelled_at is null
  and coalesce(o.fulfillment_status, '') not in ('FULFILLED', 'FULFILLMENT_NOT_REQUIRED')
  and not exists (select 1 from ops.shipments sh where sh.order_id = o.id);

revoke all on ops.flow_board from public, anon, authenticated;
grant select on ops.flow_board to service_role;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant select on ops.flow_board to flowmerce_app';
  end if;
end $$;

notify pgrst, 'reload schema';

-- ##################################################################### 108_flow_board_amazon.sql
-- 108: the Shipping board learns what Amazon (MCF) says.  Read-only view; safe to run more than once. Needs 107.
--
-- Amazon does not tell Shopify when it ships or delivers an MCF order, so many orders sent through Amazon still show
-- "unfulfilled" in Shopify. The hub keeps its own Amazon check per order in public.hub_orders (o->'pkgs', packages
-- with route 'mcf': Amazon's latest status, when, the tracking number Amazon gave, the MCF order id).
-- This view adds that to every row, and an order that Shopify shows as unfulfilled but Amazon has a package for
-- becomes one 'amazon' row per Amazon package instead of a 'not dispatched' order.
--
-- Columns are only ADDED at the end (amazon_*), so 107's columns keep their positions.
-- Coverage: hub_orders holds the hub's recent orders only (from about 12 Oct 2026); older orders have no Amazon data.

create or replace view ops.flow_board with (security_invoker = true) as
with hub as (
  select p.id,
         nullif(coalesce(p.raw->'shippingAddress'->>'city', p.raw->'shipping_address'->>'city'), '')               as ship_city,
         nullif(coalesce(p.raw->'shippingAddress'->>'provinceCode', p.raw->'shipping_address'->>'province_code'), '') as ship_state,
         coalesce(p.raw->>'note', '') ~* '\mdone\M'                                                                   as note_done
  from public.orders p
),
amz as (   -- one row per Amazon (MCF) package the hub knows
  select h.order_id::bigint                                                          as order_id,
         p.n                                                                         as pkg_no,
         nullif(p.pkg->'last'->>'text', '')                                          as amazon_status,
         case when (p.pkg->'last'->>'at') ~ '^\d+$'
              then to_timestamp((p.pkg->'last'->>'at')::bigint / 1000.0) end         as amazon_at,
         nullif(p.pkg->>'mcfId', '')                                                 as amazon_ref,
         nullif(p.pkg->'trk'->>0, '')                                                as amazon_tracking,
         case when (p.pkg->>'checkedAt') ~ '^\d+$'
              then to_timestamp((p.pkg->>'checkedAt')::bigint / 1000.0) end          as amazon_checked_at
  from public.hub_orders h
  cross join lateral jsonb_array_elements(case when jsonb_typeof(h.o->'pkgs') = 'array' then h.o->'pkgs' else '[]'::jsonb end)
             with ordinality as p(pkg, n)
  where p.pkg->>'route' = 'mcf'
    and h.order_id::text ~ '^\d+$'
),
amz_order as (   -- per order: the latest Amazon word, for rows that already have a Shopify fulfilment
  select distinct on (order_id) order_id, amazon_status, amazon_at, amazon_ref, amazon_tracking, amazon_checked_at
  from amz order by order_id, amazon_at desc nulls last
)
select 'tracking'::text                 as row_kind,
       t.tracking_id::text              as row_id,
       t.tracking_id,
       t.store, t.order_id, t.order_name, t.placed_at,
       t.shipment_id, t.kind,
       t.carrier_name, t.tracking_number, t.track_url,
       t.status, t.raw_status, t.source,
       -- dispatched = the earlier of Shopify's fulfilment and the carrier's first movement: a parcel Amazon sent on
       -- 5 Nov but entered in Shopify on 19 Nov (# RBP8183) is 14 days old, not 0
       least(t.shipped_at, tk.picked_up_at) as shipped_at, t.last_scan_at, t.last_scan_place, sh.last_scan_text,
       t.delivered_at, t.eta, t.last_check_ok_at,
       t.team_mark, t.team_mark_at,
       t.open_exceptions,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false) as note_done,
       a.amazon_status, a.amazon_at, a.amazon_ref, a.amazon_tracking, a.amazon_checked_at
from ops.shipment_list t
join ops.shipments sh on sh.id = t.shipment_id
join ops.orders o     on o.id  = t.order_id
left join ops.tracking_numbers tk on tk.id = t.tracking_id
left join hub h       on h.id  = t.order_id
left join amz_order a on a.order_id = t.order_id

union all

-- A fulfilment with no tracking row of its own. Usually Shopify has no number for it. But two orders sent in ONE
-- parcel share one number, and the number's tracking row belongs to only one of them (e.g. CPC #6948 and #6949,
-- DHL 4503128464): the other order then reads that shared parcel's number, status and last scan, so it is neither
-- "no tracking number" nor stuck once the parcel is delivered. Dispatch time is the fulfilment's own time, not
-- when Flowmerce first stored the row.
select 'shipment', sh.id::text, null::uuid,
       sh.store, o.id, o.name, o.placed_at,
       sh.id, sh.kind,
       coalesce(c.name, nullif(sh.carrier, '')), tn.tracking_number, null::text,
       coalesce(tn.status, 'pending'), tn.raw_status, 'shopify'::text,
       least(coalesce(case when (sh.step_times->>'shipped') ~ '^\d{4}-' then (sh.step_times->>'shipped')::timestamptz end,
                      sh.created_at),
             case when (sh.step_times->>'transit') ~ '^\d{4}-' then (sh.step_times->>'transit')::timestamptz end),
       tn.last_scan_at, coalesce(sh.last_scan_place, tn.last_scan_place), coalesce(sh.last_scan_text, tn.last_scan_text),
       coalesce(sh.delivered_at, tn.delivered_at), coalesce(sh.eta, tn.eta), tn.last_check_ok_at,
       null::text, null::timestamptz,
       0,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false),
       a.amazon_status, a.amazon_at, a.amazon_ref, a.amazon_tracking, a.amazon_checked_at
from ops.shipments sh
join ops.orders o on o.id = sh.order_id
left join ops.carriers c on c.id = sh.carrier_id
left join hub h on h.id = o.id
left join amz_order a on a.order_id = o.id
left join lateral (select t.tracking_number, t.status, t.raw_status, t.last_scan_at, t.delivered_at, t.eta,
                          t.last_check_ok_at, s2.last_scan_place, s2.last_scan_text
                     from ops.tracking_numbers t
                     join ops.shipments s2 on s2.id = t.shipment_id
                    where t.carrier_id = sh.carrier_id and t.store = sh.store
                      and t.tracking_number = any(sh.tracking)
                    order by (t.status = 'delivered') desc, t.updated_at desc
                    limit 1) tn on true
where sh.step not in ('cancelled')
  and not exists (select 1 from ops.tracking_numbers t where t.shipment_id = sh.id)

union all

-- Shopify: unfulfilled, no fulfilment. Amazon: has a package for it -> one row per Amazon package.
select 'amazon', o.id::text || ':' || az.pkg_no::text, null::uuid,
       o.store, o.id, o.name, o.placed_at,
       null::uuid, 'mcf'::text,
       case when az.amazon_tracking ~* '^TBA'                     then 'Amazon Logistics US'
            when az.amazon_tracking ~ '^(9[2-5]\d{18,24})$'       then 'USPS'
            when az.amazon_tracking ~* '^1Z'                      then 'UPS'
            when az.amazon_tracking is not null                   then 'Amazon (carrier not named)'
            else 'Amazon Logistics US' end,
       az.amazon_tracking,
       case when az.amazon_tracking ~* '^TBA'               then 'https://track.amazon.com/tracking/' || az.amazon_tracking
            when az.amazon_tracking ~ '^(9[2-5]\d{18,24})$' then 'https://tools.usps.com/go/TrackConfirmAction?tLabels=' || az.amazon_tracking
            when az.amazon_tracking ~* '^1Z'                then 'https://www.ups.com/track?tracknum=' || az.amazon_tracking end,
       'pending'::text, az.amazon_status, 'amazon'::text,
       case when az.amazon_status ~* 'shipped' then az.amazon_at end, null::timestamptz, null::text,
       'Amazon: ' || coalesce(az.amazon_status, 'request sent, no answer yet'),
       null::timestamptz, null::date, az.amazon_checked_at,
       null::text, null::timestamptz,
       0,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false),
       az.amazon_status, az.amazon_at, az.amazon_ref, az.amazon_tracking, az.amazon_checked_at
from ops.orders o
join amz az on az.order_id = o.id
left join hub h on h.id = o.id
where o.placed_at > now() - interval '60 days'
  and o.cancelled_at is null
  and coalesce(o.fulfillment_status, '') not in ('FULFILLED', 'FULFILLMENT_NOT_REQUIRED')
  and not exists (select 1 from ops.shipments sh where sh.order_id = o.id)

union all

select 'order', o.id::text, null::uuid,
       o.store, o.id, o.name, o.placed_at,
       null::uuid, null::text,
       null::text, null::text, null::text,
       null::text, null::text, null::text,
       null::timestamptz, null::timestamptz, null::text, null::text,
       null::timestamptz, null::date, null::timestamptz,
       null::text, null::timestamptz,
       0,
       o.total, o.currency, o.financial_status, o.fulfillment_status, o.cancelled_at,
       h.ship_city, h.ship_state, coalesce(h.note_done, false),
       null::text, null::timestamptz, null::text, null::text, null::timestamptz
from ops.orders o
left join hub h on h.id = o.id
where o.placed_at > now() - interval '60 days'
  and o.cancelled_at is null
  and coalesce(o.fulfillment_status, '') not in ('FULFILLED', 'FULFILLMENT_NOT_REQUIRED')
  and not exists (select 1 from ops.shipments sh where sh.order_id = o.id)
  and not exists (select 1 from amz where amz.order_id = o.id);

revoke all on ops.flow_board from public, anon, authenticated;
grant select on ops.flow_board to service_role;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant select on ops.flow_board to flowmerce_app';
  end if;
end $$;

notify pgrst, 'reload schema';

-- ##################################################################### 109_amazon_mcf_intake.sql
-- 109: where the Amazon Multi-Channel Fulfillment (MCF) data goes, and the read-only view Flowmerce reads.
-- Safe to run more than once. Changes no existing table.
--
-- Amazon does not tell Shopify when it ships or delivers an MCF order. The team loads Amazon's own API answers here
-- (Selling Partner API, Fulfillment Outbound v2020-07-01), unchanged, as JSON:
--
--   ops.amazon_mcf_orders    one row per MCF order:   the `payload` of getFulfillmentOrder
--                            ({ fulfillmentOrder, fulfillmentOrderItems, fulfillmentShipments, ... })
--   ops.amazon_mcf_tracking  one row per package:     the `payload` of getPackageTrackingDetails
--                            ({ packageNumber, trackingNumber, carrierCode, currentStatus, trackingEvents, ... })
--
-- Load again whenever Amazon has news: insert ... on conflict (key) do update set payload = excluded.payload.
-- Flowmerce only reads ops.amazon_mcf_packages (below), which keeps NO name, street address, phone or e-mail.

create table if not exists ops.amazon_mcf_orders (
  seller_fulfillment_order_id text primary key,       -- fulfillmentOrder.sellerFulfillmentOrderId
  store        text references ops.stores(id),        -- RBP or CPC (optional; leave empty if not known)
  payload      jsonb not null,                         -- getFulfillmentOrder payload, unchanged
  fetched_at   timestamptz not null default now()
);

create table if not exists ops.amazon_mcf_tracking (
  package_number text primary key,                     -- packageNumber (as text)
  payload      jsonb not null,                         -- getPackageTrackingDetails payload, unchanged
  fetched_at   timestamptz not null default now()
);

create index if not exists amazon_mcf_tracking_number on ops.amazon_mcf_tracking ((upper(payload->>'trackingNumber')));

alter table ops.amazon_mcf_orders   enable row level security;
alter table ops.amazon_mcf_tracking enable row level security;
revoke all on ops.amazon_mcf_orders, ops.amazon_mcf_tracking from public, anon, authenticated;
grant select, insert, update, delete on ops.amazon_mcf_orders, ops.amazon_mcf_tracking to service_role;

-- One row per Amazon package (or per MCF order that has no package yet). No personal data.
-- When 111 (the MCF sheet table) exists, 111 owns this view (it adds the sheet's rows): 109 leaves it alone.
do $v$ begin
  if to_regclass('ops.amazon_mcf_sheet') is null then
    execute 'drop view if exists ops.amazon_mcf_packages';
    execute $q$create view ops.amazon_mcf_packages with (security_invoker = true) as
with o as (
  select m.seller_fulfillment_order_id                                   as sfo_id,
         m.store,
         m.payload->'fulfillmentOrder'                                   as fo,
         m.payload->'fulfillmentShipments'                               as shipments,
         m.payload->'fulfillmentOrderItems'                              as items,
         m.fetched_at
  from ops.amazon_mcf_orders m
),
pk as (   -- packages inside the order's shipments
  select o.sfo_id, s.shp, p.pkg
  from o
  cross join lateral jsonb_array_elements(case when jsonb_typeof(o.shipments) = 'array' then o.shipments else '[]'::jsonb end) s(shp)
  cross join lateral jsonb_array_elements(case when jsonb_typeof(s.shp->'fulfillmentShipmentPackage') = 'array'
                                               then s.shp->'fulfillmentShipmentPackage' else '[]'::jsonb end) p(pkg)
)
select o.sfo_id,
       o.store,
       o.fo->>'displayableOrderId'                                         as displayable_order_id,
       o.fo->>'fulfillmentOrderStatus'                                     as order_status,
       nullif(o.fo->>'receivedDate', '')::timestamptz                       as received_at,
       nullif(o.fo->>'statusUpdatedDate', '')::timestamptz                  as order_status_at,
       (select coalesce(jsonb_agg(jsonb_build_object('sku', i->>'sellerSku', 'qty', (i->>'quantity')::int)), '[]'::jsonb)
          from jsonb_array_elements(case when jsonb_typeof(o.items) = 'array' then o.items else '[]'::jsonb end) i) as items,
       pk.shp->>'amazonShipmentId'                                         as amazon_shipment_id,
       pk.shp->>'fulfillmentShipmentStatus'                                as shipment_status,
       nullif(pk.shp->>'shippingDate', '')::timestamptz                     as shipped_at,
       pk.pkg->>'packageNumber'                                            as package_number,
       coalesce(nullif(t.payload->>'trackingNumber', ''), nullif(pk.pkg->>'trackingNumber', '')) as tracking_number,
       coalesce(nullif(t.payload->>'carrierCode', ''), nullif(pk.pkg->>'carrierCode', ''))       as carrier_code,
       coalesce(nullif(t.payload->>'estimatedArrivalDate', ''), nullif(pk.pkg->>'estimatedArrivalDate', ''),
                nullif(pk.shp->>'estimatedArrivalDate', ''))::timestamptz   as estimated_arrival,
       t.payload->>'currentStatus'                                         as tracking_status,
       t.payload->>'currentStatusDescription'                              as tracking_status_text,
       case when t.payload->>'currentStatus' = 'DELIVERED'                -- delivered: the time of Amazon's latest event
            then coalesce(ev.last_event_at, t.fetched_at) end               as delivered_at,
       ev.last_event_at, ev.last_event_text, ev.last_event_city, ev.last_event_state,
       (select coalesce(jsonb_agg(jsonb_build_object('at', e->>'eventDate', 'code', e->>'eventCode',
                                                     'text', e->>'eventDescription',
                                                     'city', e->'eventAddress'->>'city', 'state', e->'eventAddress'->>'state',
                                                     'country', e->'eventAddress'->>'country')
                                  order by e->>'eventDate'), '[]'::jsonb)
          from jsonb_array_elements(case when jsonb_typeof(t.payload->'trackingEvents') = 'array' then t.payload->'trackingEvents' else '[]'::jsonb end) e) as events,
       greatest(o.fetched_at, t.fetched_at)                                as fetched_at
from o
left join pk on pk.sfo_id = o.sfo_id
left join ops.amazon_mcf_tracking t on t.package_number = pk.pkg->>'packageNumber'
left join lateral (
  select nullif(e->>'eventDate', '')::timestamptz as last_event_at, e->>'eventDescription' as last_event_text,
         e->'eventAddress'->>'city' as last_event_city, e->'eventAddress'->>'state' as last_event_state
  from jsonb_array_elements(case when jsonb_typeof(t.payload->'trackingEvents') = 'array' then t.payload->'trackingEvents' else '[]'::jsonb end) e
  order by nullif(e->>'eventDate', '')::timestamptz desc nulls last limit 1
) ev on true$q$;
  end if;
end $v$;

revoke all on ops.amazon_mcf_packages from public, anon, authenticated;
grant select on ops.amazon_mcf_packages to service_role;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant select on ops.amazon_mcf_packages to flowmerce_app';
  end if;
end $$;

notify pgrst, 'reload schema';

-- ##################################################################### 111_amazon_mcf_sheet.sql
-- 111: the team's Amazon MCF tracking sheet, copied into Supabase once a day by Flowmerce.
-- Safe to run more than once. Adds one table and widens the view ops.amazon_mcf_packages (109); changes no data.
--
-- The sheet ("Sellora MCF Tracking", tab Tracking) is refreshed from Amazon every morning around 04:30-05:00 IST.
-- Flowmerce reads it at 09:00 IST through its Google service account and upserts every row here (key: MCF id +
-- parcel). Rows are never deleted: an MCF order that later leaves the sheet keeps its last known state, and
-- synced_at says when the sheet last showed it. Each sync is logged in ops.sync_runs (source 'amazon', kind 'import').
--
-- No personal data: no customer name (the sheet's Order column sometimes holds one; only an order number is kept),
-- no street address, no link. last_event_city / _state are the city and state of Amazon's last scan.

create table if not exists ops.amazon_mcf_sheet (
  sfo_id               text not null,                     -- MCF id (seller fulfillment order id)
  package_key          text not null default '',          -- Parcel (Amazon package number), '' until Amazon packs it
  store                text references ops.stores(id),    -- RBP (Ridhi) or CPC
  order_number         text,                               -- Shopify order number digits; null when the sheet has none
  order_status         text,                               -- Amazon order status: Complete, Processing, Planning, ...
  received_on          date,
  speed                text,                               -- Standard / Expedited / Priority
  tracking_number      text,
  carrier              text,
  shipped_on           date,
  arrives_by           date,
  tracking_status      text,                               -- DELIVERED, IN_TRANSIT, OUT_FOR_DELIVERY, DELAYED, ...
  tracking_status_text text,                               -- Amazon's last scan text
  delivered_at         timestamptz,
  last_event_at        timestamptz,
  last_event_city      text,
  last_event_state     text,
  sheet_flag           text,                               -- the sheet's own Flag column
  checked_at           timestamptz,                        -- when the team's tool last asked Amazon
  first_synced_at      timestamptz not null default now(),
  synced_at            timestamptz not null default now(), -- the last sync that saw this row in the sheet
  primary key (sfo_id, package_key)
);

create index if not exists amazon_mcf_sheet_tracking on ops.amazon_mcf_sheet (upper(tracking_number));
create index if not exists amazon_mcf_sheet_order on ops.amazon_mcf_sheet (store, order_number);

alter table ops.amazon_mcf_sheet enable row level security;
revoke all on ops.amazon_mcf_sheet from public, anon, authenticated;
grant select, insert, update, delete on ops.amazon_mcf_sheet to service_role;

-- 109's view, plus the sheet's rows (an MCF order loaded from Amazon's API, in 109's tables, wins over the sheet).
-- Two columns are added at the end: source ('amazon_api' / 'sheet') and synced_at.
drop view if exists ops.amazon_mcf_packages;   -- recreated below (109 and 111 may be re-run in any order)
create view ops.amazon_mcf_packages with (security_invoker = true) as
with o as (
  select m.seller_fulfillment_order_id                                   as sfo_id,
         m.store,
         m.payload->'fulfillmentOrder'                                   as fo,
         m.payload->'fulfillmentShipments'                               as shipments,
         m.payload->'fulfillmentOrderItems'                              as items,
         m.fetched_at
  from ops.amazon_mcf_orders m
),
pk as (   -- packages inside the order's shipments
  select o.sfo_id, s.shp, p.pkg
  from o
  cross join lateral jsonb_array_elements(case when jsonb_typeof(o.shipments) = 'array' then o.shipments else '[]'::jsonb end) s(shp)
  cross join lateral jsonb_array_elements(case when jsonb_typeof(s.shp->'fulfillmentShipmentPackage') = 'array'
                                               then s.shp->'fulfillmentShipmentPackage' else '[]'::jsonb end) p(pkg)
)
select o.sfo_id,
       o.store,
       o.fo->>'displayableOrderId'                                         as displayable_order_id,
       o.fo->>'fulfillmentOrderStatus'                                     as order_status,
       nullif(o.fo->>'receivedDate', '')::timestamptz                       as received_at,
       nullif(o.fo->>'statusUpdatedDate', '')::timestamptz                  as order_status_at,
       (select coalesce(jsonb_agg(jsonb_build_object('sku', i->>'sellerSku', 'qty', (i->>'quantity')::int)), '[]'::jsonb)
          from jsonb_array_elements(case when jsonb_typeof(o.items) = 'array' then o.items else '[]'::jsonb end) i) as items,
       pk.shp->>'amazonShipmentId'                                         as amazon_shipment_id,
       pk.shp->>'fulfillmentShipmentStatus'                                as shipment_status,
       nullif(pk.shp->>'shippingDate', '')::timestamptz                     as shipped_at,
       pk.pkg->>'packageNumber'                                            as package_number,
       coalesce(nullif(t.payload->>'trackingNumber', ''), nullif(pk.pkg->>'trackingNumber', '')) as tracking_number,
       coalesce(nullif(t.payload->>'carrierCode', ''), nullif(pk.pkg->>'carrierCode', ''))       as carrier_code,
       coalesce(nullif(t.payload->>'estimatedArrivalDate', ''), nullif(pk.pkg->>'estimatedArrivalDate', ''),
                nullif(pk.shp->>'estimatedArrivalDate', ''))::timestamptz   as estimated_arrival,
       t.payload->>'currentStatus'                                         as tracking_status,
       t.payload->>'currentStatusDescription'                              as tracking_status_text,
       case when t.payload->>'currentStatus' = 'DELIVERED'                -- delivered: the time of Amazon's latest event
            then coalesce(ev.last_event_at, t.fetched_at) end               as delivered_at,
       ev.last_event_at, ev.last_event_text, ev.last_event_city, ev.last_event_state,
       (select coalesce(jsonb_agg(jsonb_build_object('at', e->>'eventDate', 'code', e->>'eventCode',
                                                     'text', e->>'eventDescription',
                                                     'city', e->'eventAddress'->>'city', 'state', e->'eventAddress'->>'state',
                                                     'country', e->'eventAddress'->>'country')
                                  order by e->>'eventDate'), '[]'::jsonb)
          from jsonb_array_elements(case when jsonb_typeof(t.payload->'trackingEvents') = 'array' then t.payload->'trackingEvents' else '[]'::jsonb end) e) as events,
       greatest(o.fetched_at, t.fetched_at)                                as fetched_at,
       'amazon_api'::text                                                  as source,
       greatest(o.fetched_at, t.fetched_at)                                as synced_at
from o
left join pk on pk.sfo_id = o.sfo_id
left join ops.amazon_mcf_tracking t on t.package_number = pk.pkg->>'packageNumber'
left join lateral (
  select nullif(e->>'eventDate', '')::timestamptz as last_event_at, e->>'eventDescription' as last_event_text,
         e->'eventAddress'->>'city' as last_event_city, e->'eventAddress'->>'state' as last_event_state
  from jsonb_array_elements(case when jsonb_typeof(t.payload->'trackingEvents') = 'array' then t.payload->'trackingEvents' else '[]'::jsonb end) e
  order by nullif(e->>'eventDate', '')::timestamptz desc nulls last limit 1
) ev on true

union all

select s.sfo_id,
       s.store,
       s.order_number                                                      as displayable_order_id,
       s.order_status,
       (s.received_on::timestamp at time zone 'UTC') as received_at,
       null::timestamptz                                                   as order_status_at,
       '[]'::jsonb                                                         as items,
       null::text                                                          as amazon_shipment_id,
       case when s.tracking_number is not null or s.shipped_on is not null then 'SHIPPED' end as shipment_status,
       (s.shipped_on::timestamp at time zone 'UTC') as shipped_at,
       nullif(s.package_key, '')                                           as package_number,
       s.tracking_number,
       s.carrier                                                           as carrier_code,
       (s.arrives_by::timestamp at time zone 'UTC') as estimated_arrival,
       s.tracking_status,
       s.tracking_status_text,
       s.delivered_at,
       s.last_event_at,
       s.tracking_status_text                                              as last_event_text,
       s.last_event_city,
       s.last_event_state,
       '[]'::jsonb                                                         as events,
       s.checked_at                                                        as fetched_at,
       'sheet'::text                                                       as source,
       s.synced_at
from ops.amazon_mcf_sheet s
where not exists (select 1 from ops.amazon_mcf_orders m where m.seller_fulfillment_order_id = s.sfo_id)
  -- the "not packed yet" row of an MCF order that has since got its parcel(s) is history, not a parcel
  and not (s.package_key = '' and exists (select 1 from ops.amazon_mcf_sheet x where x.sfo_id = s.sfo_id and x.package_key <> ''));

revoke all on ops.amazon_mcf_packages from public, anon, authenticated;
grant select on ops.amazon_mcf_packages to service_role;
do $$ begin
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant select on ops.amazon_mcf_packages to flowmerce_app';
    execute 'grant select on ops.amazon_mcf_sheet to flowmerce_app';
  end if;
end $$;

notify pgrst, 'reload schema';

-- ##################################################################### 112_cro.sql
-- =====================================================================================
-- Flowmerce central database · 112 · CRO (Conversion Rate Optimization) module
-- Safe to run more than once. Creates the schema `cro`; reads ops.orders / ops.stores; never writes ops.*,
-- seo.* or public.*.
--
-- What lives here (only what is CRO's own; orders and stores stay in ops):
--   cro.store_settings  one row per store: whether CRO alarms run for it
--   cro.alarm_rules     alarm thresholds the team can edit (conversion-rate drop, no orders for a product keyword)
--   cro.alerts          every alarm that fired, open until resolved
--   cro.change_log      what the team changed on the store (theme, app, price, promo, ad), typed in by hand
--   cro.daily_sales     view: orders and revenue per store per local day, from ops.orders
--
-- Conversion rate, sessions and the funnel are NOT stored: Flowmerce asks Shopify (ShopifyQL) when a page needs them.
-- No personal data: no customer names, emails or addresses are stored here.
--
-- After running: Project Settings -> Data API -> Exposed schemas -> add "cro" (next to "ops").
-- =====================================================================================

create schema if not exists cro;
comment on schema cro is 'Flowmerce CRO module: alarm rules, alerts, change log, per-store settings. Orders stay in ops.';

-- ---------------------------------------------------------------- store_settings
create table if not exists cro.store_settings (
  store           text primary key references ops.stores(id),
  alarms_enabled  boolean not null default true,
  updated_by      text,
  updated_at      timestamptz not null default now()
);
comment on table cro.store_settings is 'Per-store CRO switches. A store without a row is treated as alarms_enabled = true.';

drop trigger if exists store_settings_updated_at on cro.store_settings;
create trigger store_settings_updated_at before update on cro.store_settings
  for each row execute function ops.set_updated_at();

-- ---------------------------------------------------------------- alarm_rules
-- kind 'cvr_drop':          fire when yesterday's conversion rate fell by threshold % or more vs the day before.
-- kind 'no_product_orders': fire when no order containing a product matching product_keyword arrived for threshold hours.
create table if not exists cro.alarm_rules (
  id               bigint generated always as identity primary key,
  store            text not null references ops.stores(id),
  kind             text not null check (kind in ('cvr_drop', 'no_product_orders')),
  title            text not null check (length(btrim(title)) between 1 and 200),
  threshold        numeric(10,2) not null check (threshold > 0),
  product_keyword  text check (product_keyword is null or length(btrim(product_keyword)) between 1 and 100),
  is_active        boolean not null default true,
  last_checked_at  timestamptz,
  created_at       timestamptz not null default now(),
  updated_by       text,
  updated_at       timestamptz not null default now(),
  constraint alarm_rules_keyword_matches_kind check (
    (kind = 'no_product_orders' and product_keyword is not null)
    or (kind = 'cvr_drop' and product_keyword is null)),
  constraint alarm_rules_cvr_threshold_is_percent check (kind <> 'cvr_drop' or threshold <= 100)
);
comment on table cro.alarm_rules is 'Editable CRO alarm rules. threshold: percent drop (cvr_drop) or hours without an order (no_product_orders).';
comment on column cro.alarm_rules.product_keyword is 'no_product_orders only: matched (case-insensitive) against product title, type and tags.';

-- One rule per store + kind + keyword.
create unique index if not exists alarm_rules_one_per_kind
  on cro.alarm_rules (store, kind, lower(coalesce(product_keyword, '')));

drop trigger if exists alarm_rules_updated_at on cro.alarm_rules;
create trigger alarm_rules_updated_at before update on cro.alarm_rules
  for each row execute function ops.set_updated_at();

-- ---------------------------------------------------------------- alerts
create table if not exists cro.alerts (
  id            bigint generated always as identity primary key,
  rule_id       bigint not null references cro.alarm_rules(id) on delete restrict,   -- keep history: rules are switched off, not deleted
  store         text not null references ops.stores(id),
  period_date   date,                                     -- cvr_drop: the store-local day that dropped; null for other kinds
  message       text not null check (length(message) between 1 and 2000),
  details       jsonb not null default '{}'::jsonb,       -- the figures behind the alert (rates, hours, order number)
  triggered_at  timestamptz not null default now(),
  resolved_at   timestamptz,
  constraint alerts_resolved_after_triggered check (resolved_at is null or resolved_at >= triggered_at)
);
comment on table cro.alerts is 'Every CRO alarm that fired. Open while resolved_at is null.';

-- At most one open alert per rule, and one conversion-drop alert per rule per day: the database refuses duplicates.
create unique index if not exists alerts_one_open_per_rule on cro.alerts (rule_id) where resolved_at is null;
create unique index if not exists alerts_one_per_rule_day on cro.alerts (rule_id, period_date) where period_date is not null;
create index if not exists alerts_store_recent on cro.alerts (store, triggered_at desc);

-- ---------------------------------------------------------------- change_log
create table if not exists cro.change_log (
  id          bigint generated always as identity primary key,
  store       text not null references ops.stores(id),
  entry_date  date not null,
  change      text not null check (length(btrim(change)) between 1 and 1000),
  area        text not null default 'other' check (area in ('theme', 'app', 'price', 'promo', 'ad', 'other')),
  owner       text check (owner is null or length(owner) <= 200),   -- who made the change on the store
  created_by  text,                                                  -- who recorded it in Flowmerce
  created_at  timestamptz not null default now()
);
comment on table cro.change_log is 'Store changes typed in by the team, shown as markers on CRO trend charts.';
create index if not exists change_log_store_date on cro.change_log (store, entry_date desc);

-- ---------------------------------------------------------------- daily_sales (view)
-- One row per store per store-local day that has orders. Cancelled orders are left out.
-- Uses only ops.orders columns the Shipping refresh fills today (placed_at, total, currency, cancelled_at,
-- financial_status). Days without orders have no row; the backend fills those gaps with zero.
create or replace view cro.daily_sales with (security_invoker = true) as
select o.store,
       (o.placed_at at time zone s.timezone)::date                                    as day,
       count(*)                                                                         as orders,
       coalesce(sum(o.total), 0)::numeric(14,2)                                         as revenue,
       count(*) filter (where o.financial_status in ('refunded', 'partially_refunded')) as refunded_orders,
       min(o.currency)                                                                  as currency
from ops.orders o
join ops.stores s on s.id = o.store
where o.cancelled_at is null
group by o.store, (o.placed_at at time zone s.timezone)::date;
comment on view cro.daily_sales is 'Orders and revenue per store per local day (ops.stores.timezone), cancelled orders excluded.';

-- ---------------------------------------------------------------- default rules
-- The two alarms the CRO prototype ran on the Ridhi store (guz0he-21): conversion-rate drop 20%, and 12 hours
-- without a quilt order. CPC gets the conversion-rate rule only; a product rule for CPC is added from the app.
-- Inserted only when missing: edits made later in the app are never overwritten.
insert into cro.alarm_rules (store, kind, title, threshold, product_keyword)
select v.store, v.kind, v.title, v.threshold, v.product_keyword
from (values
  ('RBP', 'cvr_drop',          'Conversion rate drop 20%',      20::numeric, null::text),
  ('RBP', 'no_product_orders', 'No quilt orders for 12 hours',  12::numeric, 'quilt'),
  ('CPC', 'cvr_drop',          'Conversion rate drop 20%',      20::numeric, null::text)
) v(store, kind, title, threshold, product_keyword)
where exists (select 1 from ops.stores s where s.id = v.store)
on conflict (store, kind, lower(coalesce(product_keyword, ''))) do nothing;

-- ---------------------------------------------------------------- security (same rules as 080)
-- RLS on, no policies: the browser keys (anon, authenticated) can read nothing. Only the backend's service_role
-- (and flowmerce_app, for a direct connection later) may read and write.
alter table cro.store_settings enable row level security;
alter table cro.alarm_rules    enable row level security;
alter table cro.alerts         enable row level security;
alter table cro.change_log     enable row level security;

revoke all on all tables in schema cro from public;

do $$
begin
  if exists (select 1 from pg_roles where rolname = 'service_role') then
    execute 'grant usage on schema cro to service_role';
    execute 'grant select, insert, update, delete on all tables in schema cro to service_role';
    execute 'grant usage, select on all sequences in schema cro to service_role';
    execute 'alter default privileges in schema cro grant select, insert, update, delete on tables to service_role';
    execute 'alter default privileges in schema cro grant usage, select on sequences to service_role';
  end if;
  if exists (select 1 from pg_roles where rolname = 'anon') then
    execute 'revoke all on all tables in schema cro from anon, authenticated';
    execute 'revoke all on schema cro from anon, authenticated';
  end if;
  if exists (select 1 from pg_roles where rolname = 'flowmerce_app') then
    execute 'grant usage on schema cro to flowmerce_app';
    execute 'grant select, insert, update, delete on all tables in schema cro to flowmerce_app';
    execute 'grant usage, select on all sequences in schema cro to flowmerce_app';
  end if;
end $$;

